function getAutoMessageDurationMs(question: QuestionSpec | undefined): number {
  if (!question || question.kind !== "message") return MESSAGE_STEP_AUTO_MIN_MS;
  const title = normalizeTextInput(question.title || "");
  const subtitle = normalizeTextInput(question.subtitle || "");
  const merged = `${title} ${subtitle}`.trim();
  const charCount = merged.length;
  const lineBonus = (question.title.match(/\n/g)?.length ?? 0) + (question.subtitle?.match(/\n/g)?.length ?? 0);
  return Math.max(
    MESSAGE_STEP_AUTO_MIN_MS,
    Math.min(
      MESSAGE_STEP_AUTO_MAX_MS,
      MESSAGE_STEP_AUTO_BASE_MS + charCount * MESSAGE_STEP_AUTO_PER_CHAR_MS + lineBonus * 220
    )
  );
}

