function normalizeTextInput(raw: string): string {
  return raw.replace(/\s+/g, " ").trim();
}

function containsArabicScript(value: string): boolean {
  return /[\u0600-\u06FF]/.test(value);
}

function transliterateLatinTokenToArabic(token: string): string {
  const normalized = token
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z]/g, "");

  if (!normalized) return token;

  const dictionary: Record<string, string> = {
    omar: "عمر",
    amine: "أمين",
    amin: "أمين",
    ahmed: "أحمد",
    mohamed: "محمد",
    mohammad: "محمد",
    mohammed: "محمد",
    muhammad: "محمد",
    youssef: "يوسف",
    youcef: "يوسف",
    yassine: "ياسين",
    yasine: "ياسين",
    mehdi: "مهدي",
    mahdi: "مهدي",
    rachid: "رشيد",
    rachidh: "رشيد",
    khalid: "خالد",
    karim: "كريم",
    adil: "عادل",
    adel: "عادل",
    reda: "رضا",
    rida: "رضا",
    zakaria: "زكريا",
    zakariya: "زكريا",
    fatima: "فاطمة",
    khadija: "خديجة",
    idrissi: "إدريسي",
    drissi: "دريسي",
    elidrissi: "الإدريسي",
    alidrissi: "الإدريسي",
    elalami: "العلامي",
    alaoui: "العلوي",
    elhajji: "الحاجي",
    benali: "بن علي",
  };

  if (dictionary[normalized]) return dictionary[normalized];

  const pairs: Array<[string, string]> = [
    ["eau", "و"],
    ["ou", "و"],
    ["oo", "و"],
    ["aa", "ا"],
    ["ee", "ي"],
    ["ii", "ي"],
    ["kh", "خ"],
    ["gh", "غ"],
    ["ch", "ش"],
    ["sh", "ش"],
    ["th", "ت"],
    ["dh", "د"],
    ["ph", "ف"],
    ["oua", "وا"],
    ["wa", "وا"],
    ["qu", "ك"],
    ["ck", "ك"],
    ["dj", "ج"],
  ];

  let rest = normalized;
  let result = "";
  const singleMap: Record<string, string> = {
    a: "ا",
    b: "ب",
    c: "ك",
    d: "د",
    e: "ي",
    f: "ف",
    g: "غ",
    h: "ه",
    i: "ي",
    j: "ج",
    k: "ك",
    l: "ل",
    m: "م",
    n: "ن",
    o: "و",
    p: "ب",
    q: "ق",
    r: "ر",
    s: "س",
    t: "ت",
    u: "و",
    v: "ف",
    w: "و",
    x: "كس",
    y: "ي",
    z: "ز",
  };

  while (rest.length > 0) {
    const pair = pairs.find(([needle]) => rest.startsWith(needle));
    if (pair) {
      result += pair[1];
      rest = rest.slice(pair[0].length);
      continue;
    }
    const char = rest[0];
    result += singleMap[char] ?? char;
    rest = rest.slice(1);
  }

  return result;
}

function getArabicDisplayName(rawName: string): string {
  const normalized = normalizeTextInput(rawName);
  if (!normalized) return "";
  if (containsArabicScript(normalized)) return normalized;
  return normalized
    .split(/[\s-]+/)
    .filter(Boolean)
    .map((part) => transliterateLatinTokenToArabic(part))
    .join(" ");
}

function normalizeNumberInput(raw: string): string {
  let value = raw.trim().replace(/،/g, ",");
  value = value.replace(/(?:dh|mad|dhs|د\.?م|درهم|دراهم)/gi, "");
  value = value.replace(/\s+/g, "");
  if (value.includes(".") && value.includes(",")) {
    if (value.lastIndexOf(",") > value.lastIndexOf(".")) {
      value = value.replace(/\./g, "").replace(",", ".");
    } else {
      value = value.replace(/,/g, "");
    }
  } else if (value.includes(",")) {
    const parts = value.split(",");
    value = parts.length === 2 && parts[1].length <= 2 ? `${parts[0]}.${parts[1]}` : parts.join("");
  } else if (value.includes(".")) {
    if (/^-?\d{1,3}(\.\d{3})+([.,]\d+)?$/.test(value)) {
      value = value.replace(/\./g, "");
    }
  }
  value = value.replace(/[^0-9.-]/g, "");
  return value;
}

function normalizePhoneInput(raw: string): string {
  const compact = raw.replace(/\s+/g, "");
  const plus = compact.startsWith("+") ? "+" : "";
  const digits = compact.replace(/[^\d]/g, "");
  if (plus) return `+${digits}`;
  return digits;
}

function normalizeEnvelopeText(raw: string): string {
  return raw.replace(/،/g, ",").replace(/\s+/g, " ").trim();
}

function containsUnsafeText(value: string): boolean {
  const lower = value.toLowerCase();
  return (
    lower.includes("http") ||
    lower.includes("https") ||
    lower.includes("www.") ||
    lower.includes(".com") ||
    lower.includes("@") ||
    lower.includes("<script") ||
    lower.includes("</")
  );
}

function containsProfanity(value: string): boolean {
  const lower = value.toLowerCase();
  return PROFANITY_TERMS.some((term) => lower.includes(term));
}

function isMoneyLikeQuestion(questionId: string): boolean {
  return (
    questionId === "S2a_salary_amount" ||
    questionId === "SWP2_last_income_amount" ||
    questionId === "F7_min_income" ||
    questionId === "M3_min_income" ||
    questionId === "RNT0_rent_amount" ||
    questionId === "HSN1_loan_monthly_amount" ||
    questionId === "HSN4a_maintenance_saving_amount" ||
    questionId === "HSN5a_with_family_amount" ||
    questionId === "E6a_support_family_amount" ||
    questionId === "TRX2_total_monthly_amount" ||
    questionId === "D8a_debt_extra_amount" ||
    questionId === "G2_goal_amount" ||
    /^G1_goal_(target_amount|current_amount)_/.test(questionId) ||
    /^FX2_amount_/.test(questionId) ||
    /^D3_debt_remaining_amount_/.test(questionId) ||
    /^D4_debt_monthly_payment_/.test(questionId) ||
    /^H3_income_profile_(min|weak|good)$/.test(questionId) ||
    /^F8_income_variation_(weak|good)$/.test(questionId) ||
    /(?:^|_)public_monthly_amount$/.test(questionId) ||
    /(?:^|_)taxi_monthly_amount$/.test(questionId) ||
    /(?:^|_)car_fuel_amount$/.test(questionId) ||
    /(?:^|_)car_insurance_amount$/.test(questionId) ||
    /(?:^|_)car_maintenance_amount$/.test(questionId) ||
    /(?:^|_)car_parking_amount$/.test(questionId) ||
    /(?:^|_)car_loan_amount$/.test(questionId) ||
    /(?:^|_)car_inspection_amount$/.test(questionId) ||
    /(?:^|_)car_tax_annual_amount$/.test(questionId) ||
    /(?:^|_)bike_fuel_amount$/.test(questionId) ||
    /(?:^|_)bike_insurance_amount$/.test(questionId) ||
    /(?:^|_)bike_maintenance_amount$/.test(questionId)
  );
}

function getNumberLimits(questionId: string): {
  hardMin: number;
  hardMax: number;
  softMin?: number;
  softMax?: number;
  integerOnly?: boolean;
} | null {
  if (questionId === "S2a_salary_amount") return { hardMin: 500, hardMax: 200000, softMin: 1000, softMax: 80000 };
  if (/^H3_income_profile_(min|weak|good)$/.test(questionId)) return { hardMin: 0, hardMax: 200000, softMax: 80000 };
  if (questionId === "F7_min_income" || /^F8_income_variation_(weak|good)$/.test(questionId))
    return { hardMin: 0, hardMax: 200000, softMax: 80000 };
  if (questionId === "M3_min_income") return { hardMin: 0, hardMax: 200000, softMax: 80000 };
  if (questionId === "RNT0_rent_amount") return { hardMin: 300, hardMax: 50000, softMax: 20000 };
  if (questionId === "HSN1_loan_monthly_amount") return { hardMin: 0, hardMax: 50000, softMax: 25000 };
  if (
    questionId === "HSN4a_maintenance_saving_amount" ||
    questionId === "HSN5a_with_family_amount" ||
    questionId === "E6a_support_family_amount"
  )
    return { hardMin: 0, hardMax: 20000, softMax: 8000 };
  if (/(?:^|_)public_monthly_amount$/.test(questionId)) return { hardMin: 0, hardMax: 5000, softMax: 2000 };
  if (/(?:^|_)taxi_monthly_amount$/.test(questionId)) return { hardMin: 0, hardMax: 8000, softMax: 3000 };
  if (/(?:^|_)car_fuel_amount$/.test(questionId)) return { hardMin: 0, hardMax: 8000, softMax: 4000 };
  if (/(?:^|_)car_insurance_amount$/.test(questionId)) return { hardMin: 0, hardMax: 30000, softMax: 15000 };
  if (/(?:^|_)car_maintenance_amount$/.test(questionId)) return { hardMin: 0, hardMax: 8000, softMax: 4000 };
  if (/(?:^|_)car_parking_amount$/.test(questionId)) return { hardMin: 0, hardMax: 5000, softMax: 2000 };
  if (/(?:^|_)car_loan_amount$/.test(questionId)) return { hardMin: 0, hardMax: 50000, softMax: 25000 };
  if (/(?:^|_)car_inspection_amount$/.test(questionId)) return { hardMin: 0, hardMax: 5000, softMax: 2000 };
  if (/(?:^|_)car_tax_annual_amount$/.test(questionId)) return { hardMin: 0, hardMax: 20000, softMax: 8000 };
  if (/(?:^|_)bike_fuel_amount$/.test(questionId)) return { hardMin: 0, hardMax: 4000, softMax: 2000 };
  if (/(?:^|_)bike_insurance_amount$/.test(questionId)) return { hardMin: 0, hardMax: 15000, softMax: 7000 };
  if (/(?:^|_)bike_maintenance_amount$/.test(questionId)) return { hardMin: 0, hardMax: 4000, softMax: 2000 };
  if (questionId === "TRX2_total_monthly_amount") return { hardMin: 0, hardMax: 15000, softMax: 8000 };
  if (/^FX2_amount_/.test(questionId)) return { hardMin: 0, hardMax: 50000, softMax: 20000 };
  if (/^D3_debt_remaining_amount_/.test(questionId)) return { hardMin: 1, hardMax: 2000000, softMax: 500000 };
  if (/^D4_debt_monthly_payment_/.test(questionId)) return { hardMin: 0, hardMax: 100000, softMax: 30000 };
  if (questionId === "D8a_debt_extra_amount") return { hardMin: 0, hardMax: 50000, softMax: 20000 };
  if (questionId === "G2_goal_amount") return { hardMin: 1, hardMax: 2000000, softMax: 500000 };
  if (/^G1_goal_target_amount_/.test(questionId)) return { hardMin: 1, hardMax: 2000000, softMax: 500000 };
  if (/^G1_goal_current_amount_/.test(questionId)) return { hardMin: 0, hardMax: 2000000, softMax: 500000 };
  if (questionId === "E2_kids_count") return { hardMin: 0, hardMax: 10, integerOnly: true };
  return null;
}

function normalizeAnswer(questionId: string, rawValue: string | string[]): string | string[] {
  if (Array.isArray(rawValue)) {
    return rawValue.map((item) => normalizeTextInput(String(item)));
  }
  if (questionId === "R1_first_name" || questionId === "R2_last_name") {
    return getArabicDisplayName(rawValue);
  }
  if (questionId === "R3_phone_number") return normalizePhoneInput(rawValue);
  if (questionId === "C1_custom_envelopes") return normalizeEnvelopeText(rawValue);
  if (isMoneyLikeQuestion(questionId) || questionId === "E2_kids_count") return normalizeNumberInput(rawValue);
  if (
    questionId === "R4_birth_date" ||
    questionId === "G3_goal_date" ||
    /^G1_goal_target_date_/.test(questionId) ||
    /^D5a_debt_target_date_/.test(questionId)
  ) {
    return rawValue.trim();
  }
  return normalizeTextInput(rawValue);
}

function shouldNormalizeInputOnChange(questionId: string): boolean {
  if (questionId === "R1_first_name" || questionId === "R2_last_name") return true;
  if (questionId === "R3_phone_number") return true;
  if (questionId === "C1_custom_envelopes") return true;
  if (isMoneyLikeQuestion(questionId) || questionId === "E2_kids_count") return true;
  if (
    questionId === "R4_birth_date" ||
    questionId === "G3_goal_date" ||
    /^G1_goal_target_date_/.test(questionId) ||
    /^D5a_debt_target_date_/.test(questionId)
  ) {
    return true;
  }
  return false;
}

function validateAnswer(questionId: string, normalizedValue: string | string[], answers: Answers): ValidationResult {
  if (Array.isArray(normalizedValue)) return { ok: true, normalized: normalizedValue };
  const value = normalizedValue;

  if (questionId === "R1_first_name" || questionId === "R2_last_name") {
    if (value.length < 2 || value.length > 30) {
      return {
        ok: false,
        severity: "hard",
        message: questionId === "R1_first_name"
          ? "سمح ليا {الاسم}… كتب غير سميتك بطريقة عادية (غير الحروف)."
          : "مزيان، دابا كتب النسب ديالك بلا روابط ولا رموز.",
        helper: questionId === "R1_first_name" ? "مثال: يوسف" : "مثال: الإدريسي",
      };
    }
    if (containsUnsafeText(value) || containsProfanity(value)) {
      return {
        ok: false,
        severity: "hard",
        message: "سمح ليا {الاسم}… هاد النص ما مناسبش. كتب اسم عادي بلا روابط/كلمات خايبة ✅",
      };
    }
  }

  if (questionId === "R3_phone_number") {
    const digits = value.replace(/[^\d]/g, "");
    if (!digits || digits.length < 9 || digits.length > 12) {
      return {
        ok: false,
        severity: "hard",
        message: "رقم الهاتف باين ماشي صحيح… كتب غير الأرقام (مثال 06XXXXXXXX).",
        helper: "06XXXXXXXX",
      };
    }
  }

  if (questionId === "R4_birth_date") {
    const birthDate = new Date(value);
    const today = new Date();
    const minBirth = new Date(today.getFullYear() - 13, today.getMonth(), today.getDate());
    if (Number.isNaN(birthDate.getTime()) || birthDate > today || birthDate > minBirth) {
      return {
        ok: false,
        severity: "hard",
        message: "تاريخ الازدياد خاصو يكون صحيح (ماشي فالمستقبل) وعمر +13.",
        helper: "اختار تاريخ صالح",
      };
    }
  }

  if (questionId === "G1_goal_name") {
    if (value.length < 2 || value.length > 40 || containsUnsafeText(value) || containsProfanity(value)) {
      return {
        ok: false,
        severity: "hard",
        message: "اسم الهدف خاصو يكون واضح وبلا روابط ولا كلمات غير مناسبة.",
        helper: "مثال: صندوق الطوارئ",
      };
    }
  }

  if (/^G1_goal_name_/.test(questionId)) {
    if (value.length < 2 || value.length > 40 || containsUnsafeText(value) || containsProfanity(value)) {
      return {
        ok: false,
        severity: "hard",
        message: "اسم الهدف خاصو يكون واضح وبلا روابط ولا كلمات غير مناسبة.",
        helper: "مثال: صندوق الطوارئ",
      };
    }
  }

  if (questionId === "G2_goal_amount" || questionId === "G3_goal_date") {
    const goalReality = buildGoalRealityCheck(answers);

    if (goalReality.status === "no_date" && questionId === "G3_goal_date" && !value) {
      const yearsNeeded =
        goalReality.estimated_months_needed && goalReality.estimated_months_needed > 0
          ? Math.ceil(goalReality.estimated_months_needed / 12)
          : null;
      return {
        ok: false,
        severity: "soft",
        warningKey: "G3_goal_date_missing_for_large_goal",
        message:
          yearsNeeded && yearsNeeded > 0
            ? `هاد الهدف كبير بزاف مقارنة مع الوضعية الحالية. تقريبياً غادي يحتاج حوالي ${yearsNeeded} سنين باش يكون واقعي، لذلك الأحسن تحدد التاريخ ديالو.`
            : "هاد الهدف كبير بزاف مقارنة مع الوضعية الحالية. الأحسن تحدد التاريخ ديالو باش نعرفو واش واقعي ولا لا.",
        helper: "حدد تاريخ تقريبي للهدف",
      };
    }

    if (goalReality.status === "ambitious") {
      return {
        ok: false,
        severity: "soft",
        warningKey: "G_goal_ambitious",
        message: `باش توصل لهاد الهدف، خاص تقريباً ${formatMad(
          goalReality.required_monthly
        )} فالشهر. الإمكانية المريحة دابا أقرب لـ ${formatMad(goalReality.realistic_monthly_cap)}.`,
        helper: "تقدر تكمل أو تخفف الهدف شوية",
      };
    }

    if (goalReality.status === "unrealistic") {
      return {
        ok: false,
        severity: "soft",
        warningKey: "G_goal_unrealistic",
        message: `باش توصل لهاد الهدف فهاد المدة، خاص تقريباً ${formatMad(
          goalReality.required_monthly
        )} فالشهر، بينما الواقعي دابا أقرب لـ ${formatMad(
          goalReality.realistic_monthly_cap
        )}. إلى بغيتي، نقص المبلغ أو زيد المدة.`,
        helper:
          goalReality.suggested_amount_by_date && goalReality.months_to_goal
            ? `المبلغ الأقرب للواقع فهاد المدة هو تقريباً ${formatMad(goalReality.suggested_amount_by_date)}`
            : "راجع المبلغ أو التاريخ",
      };
    }

    if (goalReality.status === "impossible_now") {
      return {
        ok: false,
        severity: "hard",
        message: `هاد الهدف ماشي واقعي دابا بهاد الدخل وفهاد المدة. باش توصل ليه، خاص تقريباً ${formatMad(
          goalReality.required_monthly
        )} فالشهر، بينما الإمكانية الحالية أقرب لـ ${formatMad(goalReality.realistic_monthly_cap)}.`,
        helper:
          goalReality.suggested_amount_by_date && goalReality.months_to_goal
            ? `إما خليه تقريباً ${formatMad(goalReality.suggested_amount_by_date)} فهاد المدة، أو زيد المدة.`
            : "راجع الهدف أو التاريخ",
      };
    }
  }

  if (/^D2_debt_name_/.test(questionId)) {
    if (value.length < 2 || value.length > 30 || containsUnsafeText(value) || containsProfanity(value)) {
      return {
        ok: false,
        severity: "hard",
        message: "سمية الدين خاصها تكون بين 2 و30 حرف وبلا روابط.",
      };
    }
  }

  if (questionId === "C1_custom_envelopes" && value) {
    if (containsUnsafeText(value) || containsProfanity(value)) {
      return {
        ok: false,
        severity: "hard",
        message: "سمح ليا… بلا روابط ولا رموز غريبة، غير أسماء أظرفة.",
      };
    }
    const items = Array.from(
      new Set(
        value
          .replace(/،/g, ",")
          .split(",")
          .map((item) => normalizeTextInput(item))
          .filter(Boolean)
          .map((item) => item.toLowerCase())
      )
    );
    if (items.length > 10) {
      return {
        ok: false,
        severity: "hard",
        message: "خليهم غير 10 دابا باش يبقى كلشي واضح.",
      };
    }
    const tooLong = items.some((item) => item.length < 2 || item.length > 24);
    if (tooLong) {
      return {
        ok: false,
        severity: "hard",
        message: "سمّي الظرف غير بجوج كلمات باش يبان مزيان فالتطبيق.",
      };
    }
  }

  if (questionId === "G3_goal_date" || /^G1_goal_target_date_/.test(questionId) || /^D5a_debt_target_date_/.test(questionId)) {
    if (value) {
      const selected = new Date(value);
      const now = new Date();
      if (Number.isNaN(selected.getTime()) || selected <= now) {
        return {
          ok: false,
          severity: "hard",
          message: "هاد التاريخ خاصو يكون فالمستقبل.",
        };
      }
    }
  }

  const limits = getNumberLimits(questionId);
  if (limits && value) {
    const parsed = Number(value);
    if (Number.isNaN(parsed)) {
      return { ok: false, severity: "hard", message: "سمح ليا {الاسم}… دخل الرقم غير بالأرقام." };
    }
    if (parsed < limits.hardMin || parsed > limits.hardMax) {
      if (questionId === "E2_kids_count") {
        return { ok: false, severity: "hard", message: "شحال من طفل؟ دخل رقم بين 0 و10." };
      }
      if (/^D3_debt_remaining_amount_/.test(questionId)) {
        return {
          ok: false,
          severity: "hard",
          message: "المبلغ المتبقي خاصو يكون بين 1 و 2,000,000 MAD.",
          helper: "راجع المبلغ المتبقي.",
        };
      }
      if (/^D4_debt_monthly_payment_/.test(questionId) || /^D4_debt_native_amount_/.test(questionId)) {
        return {
          ok: false,
          severity: "hard",
          message: "الأداء الحالي خاصو يكون بين 0 و 100,000 MAD.",
          helper: "راجع مبلغ الأداء الحالي.",
        };
      }
      return { ok: false, severity: "hard", message: "القيمة خارجة على النطاق المسموح." };
    }
    if (limits.integerOnly && !Number.isInteger(parsed)) {
      return { ok: false, severity: "hard", message: "خاصك تدخل رقم صحيح بلا فاصلة." };
    }
    if (typeof limits.softMax === "number" && parsed > limits.softMax) {
      return {
        ok: false,
        severity: "soft",
        message: "هاد الرقم كبير شوية… واش متأكد؟ إلا متأكد عاود دخلو.",
        warningKey: questionId,
      };
    }
    if (typeof limits.softMin === "number" && parsed < limits.softMin) {
      return {
        ok: false,
        severity: "soft",
        message: "هاد الرقم صغير شوية… واش متأكد؟ إلا متأكد عاود دخلو.",
        warningKey: questionId,
      };
    }
  }

  if (/^D4_debt_monthly_payment_/.test(questionId)) {
    const idx = questionId.split("_").pop();
    const remaining = Number(getString(answers, `D3_debt_remaining_amount_${idx}`));
    const monthly = Number(value);
    if (!Number.isNaN(remaining) && !Number.isNaN(monthly) && remaining > 0 && monthly > remaining) {
      return {
        ok: false,
        severity: "soft",
        message: "القسط أكبر من المتبقي… واش متأكد؟",
        warningKey: questionId,
      };
    }
  }

  if (questionId === "D8a_debt_extra_amount") {
    const parsed = Number(value);
    const suggested = getSuggestedDebtExtraPerCycle(answers);
    if (!Number.isNaN(parsed) && suggested > 0) {
      if (parsed > suggested * 1.4) {
        return {
          ok: false,
          severity: "hard",
          message: `هاد الزيادة باينة طالعة بزاف على الإمكانية الحالية. حاول تبقى قريب من ${formatMad(
            suggested
          )} ${getCycleContributionLabel(answers)} باش الخطة تبقى واقعية.`,
        };
      }
      if (parsed > suggested) {
        return {
          ok: false,
          severity: "soft",
          warningKey: questionId,
          message: `هاد المبلغ أكبر من الاقتراح الواقعي دابا (${formatMad(
            suggested
          )} ${getCycleContributionLabel(answers)}). إلى متأكد، عاود أكد.`,
        };
      }
    }
  }

  return { ok: true, normalized: value };
}

function proposalSortValue(groupKey: EnvelopeProposalDomain): number {
  const index = PROPOSAL_DOMAIN_ORDER.indexOf(groupKey);
  return index >= 0 ? index : PROPOSAL_DOMAIN_ORDER.length;
}

function isSystemProposalName(name: string): boolean {
  return SYSTEM_PROPOSAL_SLUGS.has(slugify(name));
}

function normalizeProposalName(name: string): string {
  return normalizeTextInput(name.replace(/\s+/g, " ").trim());
}

function getDistributionNameEquivalentKey(name: string): string {
  const normalized = normalizeProposalName(name);
  if (!normalized) return "";
  if (normalized === "الماكلة") return "food";
  if (normalized === "الصحة") return "health";
  if (normalized === "مصاريف السكن") return "housing_charges";
  if (normalized === "الدار") return "maison";
  if (normalized === "صيانة الدار") return "entretien_maison";
  if (normalized === "الطوارئ" || normalized === "طوارئ") return "emergency_buffer";
  if (normalized === "التوازن") return "balance_buffer";
  if (normalized === "النقل العمومي") return "public_transport";
  if (normalized === "تاكسي / نقل خاص" || normalized === "طاكسي / إندرايف") return "taxi_private";
  if (normalized === "الترفيه") return "entertainment";
  if (normalized === "المطاعم" || normalized === "مطاعم") return "restaurants";
  if (normalized === "الشوبينغ" || normalized === "التسوق") return "shopping";
  if (normalized === "المرونة") return "flexibility";
  if (
    normalized === "لفواتير" ||
    normalized === "الفواتير" ||
    normalized === "لفواتير الثابتة" ||
    normalized === "الفواتير الثابتة"
  ) {
    return "bills";
  }
  if (normalized === "مساعدة العائلة") return "family_aid";
  if (normalized === "الباقي الحر") return "free_balance";
  const slug = slugify(normalized);
  if (!slug) return normalized;
  if (slug === "nourriture" || slug === "courses" || slug === "food") return "food";
  if (slug === "sante" || slug === "pharmacie" || slug === "health") return "health";
  if (slug === "charges" || slug === "housing_charges") return "housing_charges";
  if (slug === "factures" || slug === "bills") return "bills";
  if (slug === "loyer" || slug === "rent") return "rent";
  if (
    slug === "imprevus" ||
    slug === "imprevu" ||
    slug === "urgences" ||
    slug === "urgence" ||
    slug === "emergency" ||
    slug === "emergencies"
  ) {
    return "emergency_buffer";
  }
  if (slug === "equilibre" || slug === "balance") return "balance_buffer";
  if (slug === "transport_public" || slug === "public_transport") return "public_transport";
  if (slug === "taxi_vtc" || slug === "taxi_indrive" || slug === "taxi_private") return "taxi_private";
  if (slug === "loisirs" || slug === "entertainment") return "entertainment";
  if (slug === "restaurants" || slug === "restaurant") return "restaurants";
  if (slug === "shopping" || slug === "shoping") return "shopping";
  if (slug === "flexibilite" || slug === "flexibility" || slug === "flex") return "flexibility";
  if (
    slug === "famille_aide" ||
    slug === "aide_famille" ||
    slug === "famille___aide" ||
    slug === "famille__aide"
  ) {
    return "family_aid";
  }
  return slug;
}

function getProposalTierRank(tier: EnvelopeProposalTier): number {
  if (tier === "core") return 0;
  if (tier === "recommended") return 1;
  return 2;
}

function getProposalTierLabelForUi(tier: EnvelopeProposalTier): string {
  if (tier === "core") return "أساسي";
  if (tier === "recommended") return "مقترح";
  return "اختياري";
}

function getObjectiveModeLabelForUi(mode: ObjectivePolicyMode): string {
  if (mode === "organize") return "تنظيم واضح";
  if (mode === "save") return "تركيز على التوفير";
  if (mode === "debt") return "تركيز على الديون";
  return "متوازن";
}

function getGranularityLabelForUi(granularity: "simple" | "balanced" | "detailed"): string {
  if (granularity === "simple") return "عرض بسيط";
  if (granularity === "detailed") return "عرض مفصل";
  return "عرض متوازن";
}

function getLifestyleBudgetPreview(
  lifestyle: string,
  monthlyAvailableAfterEssentials: number | null
): {
  levelLabel: string;
  monthlyTarget: number | null;
  monthlyMin: number | null;
  monthlyMax: number | null;
  remainingAfterLifestyle: number | null;
  envelopeHint: string;
  note: string;
} {
  const normalizedLifestyle = lifestyle === "low" || lifestyle === "medium" || lifestyle === "high" ? lifestyle : "high";
  const config =
    normalizedLifestyle === "low"
      ? {
          levelLabel: "قليل",
          minShare: 0.05,
          targetShare: 0.08,
          maxShare: 0.1,
          envelopeHint: "غالباً ظرف واحد للمعيشة كافي فهاد المستوى.",
          note: "الأولوية هنا للضروري، والمرونة كتبقى خفيفة.",
        }
      : normalizedLifestyle === "high"
      ? {
          levelLabel: "مريح",
          minShare: 0.15,
          targetShare: 0.18,
          maxShare: 0.22,
          envelopeHint: "نخليو المعيشة ظاهرة بأكثر من ظرف إذا احتاج الأمر.",
          note: "كتعطي هامش أكبر لراحة اليومي، مع متابعة الباقي.",
        }
      : {
          levelLabel: "معقول",
          minShare: 0.1,
          targetShare: 0.13,
          maxShare: 0.16,
          envelopeHint: "عادة كيبقى التتبع واضح بلا كثرة الأظرفة.",
          note: "توازن بين المرونة اليومية والالتزامات الأساسية.",
        };

  if (!monthlyAvailableAfterEssentials || monthlyAvailableAfterEssentials <= 0) {
    return {
      levelLabel: config.levelLabel,
      monthlyTarget: null,
      monthlyMin: null,
      monthlyMax: null,
      remainingAfterLifestyle: null,
      envelopeHint: config.envelopeHint,
      note: "منين يتوضح الدخل أكثر، غادي نخرجو ليك التقدير بالدرهم بدقة.",
    };
  }

  const monthlyMin = roundAmount(monthlyAvailableAfterEssentials * config.minShare);
  const monthlyTarget = roundAmount(monthlyAvailableAfterEssentials * config.targetShare);
  const monthlyMax = roundAmount(monthlyAvailableAfterEssentials * config.maxShare);
  const remainingAfterLifestyle = roundAmount(
    Math.max(0, monthlyAvailableAfterEssentials - monthlyTarget)
  );

  return {
    levelLabel: config.levelLabel,
    monthlyTarget,
    monthlyMin,
    monthlyMax,
    remainingAfterLifestyle,
    envelopeHint: config.envelopeHint,
    note: config.note,
  };
}

function resolveObjectivePolicyMode(objectiveValues: string[]): ObjectivePolicyMode {
  const normalized = Array.from(new Set(objectiveValues.filter(Boolean)));
  if (normalized.includes("all")) return "balanced";
  if (normalized.length === 1) {
    if (normalized[0] === "spending_control") return "organize";
    if (normalized[0] === "savings") return "save";
    if (normalized[0] === "debt") return "debt";
    if (normalized[0] === "goals") return "balanced";
  }
  if (normalized.length > 1) return "balanced";
  return "organize";
}

function getGuidanceDirectionSnapshot(answers: Answers): GuidanceDirectionSnapshot | null {
  const mode = getString(answers, "F1_guidance_mode") as GuidancePresetMode;
  if (
    mode !== "debt_relief_first" &&
    mode !== "stability_first" &&
    mode !== "goal_growth_first" &&
    mode !== "balanced_rebuild"
  ) {
    return null;
  }

  const keepSafety = getString(answers, "F1_guidance_keep_safety") !== "no";
  const keepFlex = getString(answers, "F1_guidance_keep_flex") !== "no";
  const plannedDebtRaw = Math.max(0, roundAmount(toNumber(getString(answers, "F1_guidance_planned_debt"))));
  const plannedReserveRaw = Math.max(0, roundAmount(toNumber(getString(answers, "F1_guidance_planned_reserve"))));
  const plannedFlexRaw = Math.max(0, roundAmount(toNumber(getString(answers, "F1_guidance_planned_flex"))));
  const plannedGoalsRaw = Math.max(0, roundAmount(toNumber(getString(answers, "F1_guidance_planned_goals"))));
  const plannedFreeRaw = Math.max(0, roundAmount(toNumber(getString(answers, "F1_guidance_planned_free"))));

  const explicitPlanTotal = roundAmount(
    plannedDebtRaw + plannedReserveRaw + plannedFlexRaw + plannedGoalsRaw + plannedFreeRaw
  );

  const buildFallbackAllocation = (
    pool: number
  ): {
    planned_debt: number;
    planned_reserve: number;
    planned_flex: number;
    planned_goals: number;
    planned_free: number;
  } => {
    if (pool <= 0) {
      return {
        planned_debt: 0,
        planned_reserve: 0,
        planned_flex: 0,
        planned_goals: 0,
        planned_free: 0,
      };
    }

    const baseShares =
      mode === "debt_relief_first"
        ? { debt: 0.6, reserve: 0.25, flex: 0.1, goals: 0.05 }
        : mode === "goal_growth_first"
        ? { debt: 0.1, reserve: 0.2, flex: 0.15, goals: 0.55 }
        : mode === "stability_first"
        ? { debt: 0.2, reserve: 0.55, flex: 0.2, goals: 0.05 }
        : { debt: 0.25, reserve: 0.3, flex: 0.25, goals: 0.2 };

    const adjusted = {
      debt: baseShares.debt,
      reserve: keepSafety ? baseShares.reserve : 0,
      flex: keepFlex ? baseShares.flex : 0,
      goals: baseShares.goals,
    };
    const totalShare = adjusted.debt + adjusted.reserve + adjusted.flex + adjusted.goals;
    if (totalShare <= 0) {
      return {
        planned_debt: 0,
        planned_reserve: 0,
        planned_flex: 0,
        planned_goals: 0,
        planned_free: roundAmount(pool),
      };
    }

    const plannedDebt = roundAmount((pool * adjusted.debt) / totalShare);
    const plannedReserve = roundAmount((pool * adjusted.reserve) / totalShare);
    const plannedFlex = roundAmount((pool * adjusted.flex) / totalShare);
    const plannedGoals = roundAmount((pool * adjusted.goals) / totalShare);
    const used = roundAmount(plannedDebt + plannedReserve + plannedFlex + plannedGoals);
    const diff = roundAmount(pool - used);

    if (Math.abs(diff) <= 0.01) {
      return {
        planned_debt: plannedDebt,
        planned_reserve: plannedReserve,
        planned_flex: plannedFlex,
        planned_goals: plannedGoals,
        planned_free: 0,
      };
    }

    const key =
      mode === "debt_relief_first"
        ? "planned_debt"
        : mode === "goal_growth_first"
        ? "planned_goals"
        : mode === "stability_first" && keepSafety
        ? "planned_reserve"
        : "planned_debt";

    const output = {
      planned_debt: plannedDebt,
      planned_reserve: plannedReserve,
      planned_flex: plannedFlex,
      planned_goals: plannedGoals,
      planned_free: 0,
    };
    output[key] = roundAmount(Math.max(0, output[key] + diff));
    return output;
  };

  const fallbackPool = roundAmount(
    Math.max(
      0,
      (computeSanity(answers).remaining ?? 0) - buildDebtSummaryMetrics(answers).current_monthly
    )
  );
  const planned =
    explicitPlanTotal > 0
      ? {
          planned_debt: plannedDebtRaw,
          planned_reserve: plannedReserveRaw,
          planned_flex: plannedFlexRaw,
          planned_goals: plannedGoalsRaw,
          planned_free: plannedFreeRaw,
        }
      : buildFallbackAllocation(fallbackPool);

  return {
    mode,
    strength_pct: Math.max(0, Math.min(100, toNumber(getString(answers, "F1_guidance_strength_pct")) || 65)),
    keep_safety: keepSafety,
    keep_flex: keepFlex,
    debt_delta: roundAmount(toNumber(getString(answers, "F1_guidance_debt_delta"))),
    reserve_delta: roundAmount(toNumber(getString(answers, "F1_guidance_reserve_delta"))),
    goal_delta: roundAmount(toNumber(getString(answers, "F1_guidance_goal_delta"))),
    flex_cut_pct: roundAmount(toNumber(getString(answers, "F1_guidance_flex_cut_pct"))),
    planned_debt: planned.planned_debt,
    planned_reserve: planned.planned_reserve,
    planned_flex: planned.planned_flex,
    planned_goals: planned.planned_goals,
    planned_free: planned.planned_free,
  };
}

function getGuidancePresetLabel(mode: GuidancePresetMode): string {
  if (mode === "debt_relief_first") return "تخفيف ضغط الدين";
  if (mode === "stability_first") return "تقوية الأمان";
  if (mode === "goal_growth_first") return "تسريع الأهداف";
  return "اتجاه متوازن";
}

function getObjectivePolicy(answers: Answers): ObjectivePolicy {
  const guidanceSnapshot = getGuidanceDirectionSnapshot(answers);
  const objectiveValues = getList(answers, "Q0b_primary_objective");
  const mode = guidanceSnapshot
    ? guidanceSnapshot.mode === "debt_relief_first"
      ? "debt"
      : guidanceSnapshot.mode === "stability_first"
      ? "save"
      : "balanced"
    : resolveObjectivePolicyMode(objectiveValues);

  if (guidanceSnapshot?.mode === "goal_growth_first") {
    return {
      objective_values: objectiveValues,
      objective_primary: objectiveValues[0] ?? null,
      mode: "balanced",
      preselect_policy: "core_plus_goals",
      rollover_profile: "buffer_and_goal_bias",
      naming_style: "explicit",
      complexity_bias: "broad",
      preview_order: ["essentials", "housing", "transport", "goals", "buffer", "bills", "debts", "family", "lifestyle", "saving", "pro"],
      helper_copy: "حضّرت ليك الأظرفة باش الأهداف يبقاو واضحين من البداية بلا ما يطيحو الضروريات.",
      auto_include_tiers: ["core", "recommended"],
    };
  }

  if (mode === "save") {
    return {
      objective_values: objectiveValues,
      objective_primary: objectiveValues[0] ?? null,
      mode,
      preselect_policy: "core_plus_saving",
      rollover_profile: "accumulating_bias",
      naming_style: "explicit",
      complexity_bias: "saving_focused",
      preview_order:
        guidanceSnapshot?.mode === "stability_first"
          ? ["essentials", "housing", "transport", "buffer", "saving", "bills", "family", "debts", "goals", "lifestyle", "pro"]
          : ["essentials", "housing", "transport", "saving", "buffer", "bills", "goals", "family", "debts", "lifestyle", "pro"],
      helper_copy:
        guidanceSnapshot?.mode === "stability_first"
          ? "ركزت ليك على الأمان والاحتياط قبل التوسع فباقي الأظرفة."
          : "ركزت ليك على الأظرفة اللي كيتجمعو مع الوقت.",
      auto_include_tiers: ["core", "recommended"],
    };
  }

  if (mode === "debt") {
    return {
      objective_values: objectiveValues,
      objective_primary: objectiveValues[0] ?? null,
      mode,
      preselect_policy: "essentials_plus_debts",
      rollover_profile: "minimal_buffer_only",
      naming_style: "explicit",
      complexity_bias: "debt_focused",
      preview_order: ["essentials", "housing", "transport", "debts", "buffer", "bills", "family", "goals", "lifestyle", "saving", "pro"],
      helper_copy: "خلّيت ليك الضروريات والديون فوق كلشي.",
      auto_include_tiers: ["core"],
    };
  }

  if (mode === "balanced") {
    return {
      objective_values: objectiveValues,
      objective_primary: objectiveValues[0] ?? null,
      mode,
      preselect_policy: "balanced_core_and_recommended",
      rollover_profile: "buffer_and_saving",
      naming_style: "explicit",
      complexity_bias: "broad",
      preview_order: ["essentials", "housing", "transport", "buffer", "saving", "bills", "family", "debts", "goals", "lifestyle", "pro"],
      helper_copy: "حضّرت ليك اقتراح متوازن باش تغطي كلشي.",
      auto_include_tiers: ["core", "recommended"],
    };
  }

  return {
    objective_values: objectiveValues,
    objective_primary: objectiveValues[0] ?? null,
    mode: "organize",
    preselect_policy: "core_only",
    rollover_profile: "buffer_only",
    naming_style: "generic",
    complexity_bias: "lean",
    preview_order: ["essentials", "housing", "transport", "buffer", "bills", "family", "debts", "goals", "lifestyle", "saving", "pro"],
    helper_copy: "خلّيتها ليك بسيطة وواضحة باش تبدا بسهولة.",
    auto_include_tiers: ["core"],
  };
}

type HousingProposalEntry = {
  name: string;
  group_key: EnvelopeProposalDomain;
  kind: "buffer" | "saving" | "goal" | "accumulating" | "spend";
  source: "baseline" | "suggested";
  reason: string;
  objective_bias_effect: string;
  fallback_tier?: EnvelopeProposalTier;
};

function getEnvelopeGranularity(answers: Answers): "simple" | "balanced" | "detailed" {
  void answers;
  return "detailed";
}

function formatPreviewDate(dateValue: string): string {
  const parsed = new Date(dateValue);
  if (Number.isNaN(parsed.getTime())) return dateValue;
  return new Intl.DateTimeFormat("fr-FR", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  }).format(parsed);
}

function getLocalTodayIso(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function getSchoolPaymentCycleLabel(answers: Answers): string | null {
  const cycle = getString(answers, "E0f_school_payment_cycle");
  if (cycle === "monthly") return "شهري";
  if (cycle === "quarterly") return "كل 3 شهور";
  if (cycle === "annual") return "سنوي";
  return null;
}

function getSchoolCycleReason(answers: Answers): string | null {
  const cycle = getString(answers, "E0f_school_payment_cycle");
  if (cycle === "monthly") {
    return "الأداء ديال المدرسة شهري، لذلك خليه ظاهر باش يبقى الالتزام واضح.";
  }
  if (cycle === "quarterly") {
    return "الأداء ديال المدرسة كيتجمع كل 3 شهور، لذلك بان بظرف واضح باش ما يفاجئكش دفعة وحدة.";
  }
  if (cycle === "annual") {
    return "الأداء ديال المدرسة سنوي، لذلك خاصو ظرف واضح باش يبقى متحسب من دابا.";
  }
  return null;
}

function getHousingLoanRemainingDurationHint(answers: Answers): string | null {
  const duration = getString(answers, "HSN2_loan_remaining_duration");
  if (duration === "lt_1_year") {
    return "القرض باقي فيه مدة قصيرة، يعني هاد الضغط قريب يخف.";
  }
  if (duration === "1_3_years") {
    return "القرض باقي فيه ما بين عام و3 سنين، يعني مازال التزام مهم ولكن المدة باينة.";
  }
  if (duration === "3_7_years") {
    return "القرض باقي فيه مدة متوسطة، لذلك خاصو يبقى واضح فالتنظيم ديال السكن.";
  }
  if (duration === "gt_7_years") {
    return "القرض باقي فيه مدة طويلة، لذلك كيبقى واحد من أهم الالتزامات الثابتة عندك.";
  }
  return null;
}

function getCoupleSharedItems(answers: Answers): Set<string> {
  if (getString(answers, "E0_household_type") !== "couple") return new Set<string>();
  if (getString(answers, "E0c_budget_mode") !== "mixed") return new Set<string>();
  return new Set(getList(answers, "E0c_shared_items"));
}

function getExtendedSharedFixedItems(answers: Answers): Set<string> {
  if (getString(answers, "E0_household_type") !== "extended_family") return new Set<string>();
  if (getString(answers, "E0sh_has_shared_fixed") !== "yes") return new Set<string>();
  return new Set(getList(answers, "E0sh_shared_fixed_items"));
}

function getHousingProposalEntries(
  answers: Answers,
  _namingStyle: ObjectivePolicy["naming_style"]
): HousingProposalEntry[] {
  const housing = getString(answers, "E3_housing_status");
  if (!housing) return [];

  const granularity = getEnvelopeGranularity(answers);
  const simpleMode = granularity === "simple";
  const detailedMode = granularity === "detailed";

  if (housing === "rent") {
    const includesCosts = getString(answers, "RNT1_rent_includes_costs") === "yes";
    const includedItems = new Set(getList(answers, "RNT1a_rent_included_items"));
    const allKnownChargesIncluded =
      includesCosts &&
      ["water", "electricity", "internet", "syndic"].every((item) => includedItems.has(item));

    const entries: HousingProposalEntry[] = [
      {
        name: "Loyer",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: "الكراء هو الأساس هنا، لذلك خصو يبان بظرف واضح بوحدو.",
        objective_bias_effect: "خلّيناه واضح وبسيط باش ما يتخلطش مع باقي المصاريف.",
      },
    ];

    if (!includesCosts || !allKnownChargesIncluded) {
      entries.push({
        name: "Factures",
        group_key: "bills",
        kind: "spend",
        source: "suggested",
        fallback_tier: simpleMode ? "recommended" : "core",
        reason: "زادينا لفواتير حيث الكراء ما كيغطيش كلشي أو مازال كاين شي جزء خارج عليه.",
        objective_bias_effect: "بقينا مفرقينها باش ما تضيعش المصاريف الثابتة مع الكراء.",
      });
    }

    if (!simpleMode && (!includesCosts || !includedItems.has("syndic"))) {
      entries.push({
        name: "Charges",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "مصاريف الدار بقات ظاهرة بوحدها حيث كاينين مصاريف ماشي داخلين كاملين فالكراء.",
        objective_bias_effect: "فصلناها باش يبان شنو سكن وشنو مصروف تابع للسكن.",
      });
    }

    return entries;
  }

  if (housing === "owner_loan") {
    const remainingDurationHint = getHousingLoanRemainingDurationHint(answers);
    const entries: HousingProposalEntry[] = [
      {
        name: "Crédit logement",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: remainingDurationHint
          ? `القرض هو أهم التزام فهاد الحالة، لذلك خصو يبان بوحدو. ${remainingDurationHint}`
          : "القرض هو أهم التزام فهاد الحالة، لذلك خصو يبان بوحدو.",
        objective_bias_effect: remainingDurationHint
          ? `ما خلطناش القرض مع مصاريف السكن الأخرى باش يبقى واضح. ${remainingDurationHint}`
          : "ما خلطناش القرض مع مصاريف السكن الأخرى باش يبقى واضح.",
      },
    ];

    if (!simpleMode) {
      entries.push({
        name: "Maison",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "زدنا ظرف الدار باش تبقى المصاريف العامة ديال السكن مجموعة فبلاصة مفهومة.",
        objective_bias_effect: "خلّيناه عام باش السكن يبقى منظم بلا تعقيد كبير.",
      });
    }

    if (detailedMode) {
      entries.push(
        {
          name: "Entretien maison",
          group_key: "housing",
          kind: "accumulating",
          source: "suggested",
          fallback_tier: "recommended",
          reason: "صيانة الدار كتبان مزيان إلا بغيتي تنظيم أكثر للمصاريف التابعة للسكن.",
          objective_bias_effect: "طلعناه غير فالوضع المفصل باش ما نكثروش الأظرفة بلا فايدة.",
        },
        {
          name: "Charges",
          group_key: "housing",
          kind: "spend",
          source: "suggested",
          fallback_tier: "optional",
          reason: "زدنا مصاريف السكن غير إلا كنت باغي التفصيل أكثر.",
          objective_bias_effect: "خليّناه ثانوي باش يبان غير ملي كتفضل تنظيم مفصل.",
        }
      );
    }

    return entries;
  }

  if (housing === "owner_no_loan") {
    const ownerFixedItems = new Set(getList(answers, "HSN3_owner_fixed_items"));
    const noneOnly = ownerFixedItems.size === 1 && ownerFixedItems.has("none");
    const hasOwnerCosts = ownerFixedItems.size > 0 && !noneOnly;
    const savesForMaintenance = getString(answers, "HSN4_maintenance_saving") === "yes";
    const entries: HousingProposalEntry[] = [
      {
        name: "Maison",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: "حتى بلا قرض، الدار خاصها تبقى واضحة فالتنظيم ديال الأظرفة.",
        objective_bias_effect: "هي الظرف الرئيسي ديال السكن فهاد الحالة.",
      },
    ];

    if (!simpleMode || savesForMaintenance || ownerFixedItems.has("maintenance")) {
      entries.push({
        name: "Entretien maison",
        group_key: "housing",
        kind: "accumulating",
        source: "suggested",
        fallback_tier: simpleMode ? "optional" : "recommended",
        reason: "صيانة الدار مهمة باش ما تتخلطش مع باقي مصاريف السكن.",
        objective_bias_effect: "كنطلعوها أكثر إلا بان من الأجوبة بلي الصيانة عندها حضور فالمصاريف.",
      });
    }

    if (hasOwnerCosts && (!simpleMode || ownerFixedItems.has("syndic") || ownerFixedItems.has("services_tax"))) {
      entries.push({
        name: "Charges",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "زدنا مصاريف السكن حيث بينتي بلي كاينين مصاريف ثابتة مرتبطة بالدار.",
        objective_bias_effect: "بقات منفصلة باش يبان الضغط الحقيقي ديال السكن.",
      });
    }

    if (hasOwnerCosts && (detailedMode || ownerFixedItems.has("housing_tax") || ownerFixedItems.has("services_tax"))) {
      entries.push({
        name: "Impôts",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: detailedMode ? "recommended" : "optional",
        reason: "الضرايب بان ليها معنى إلا كان عندك هاد النوع من مصاريف السكن.",
        objective_bias_effect: "خلّيناها تبان غير ملي تكون عندها قيمة فعلية فالمعطيات.",
      });
    }

    return entries;
  }

  if (housing === "with_family") {
    const contributes = getString(answers, "HSN5_with_family_contribution") === "yes";
    const contributionTypes = new Set(getList(answers, "HSN6_with_family_contribution_types"));
    if (!contributes) return [];

    const entries: HousingProposalEntry[] = [
      {
        name: "Contribution famille",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: "الواقع هنا هو المساهمة للعائلة، لذلك سمّيناه بهاد الشكل مباشرة.",
        objective_bias_effect: "ما اقترحناش الكراء ولا القرض حيث ما كيعكسوش الحالة ديالك.",
      },
    ];

    if (detailedMode && contributionTypes.has("other")) {
      entries.push({
        name: "Charges",
        group_key: "housing",
        kind: "spend",
        source: "suggested",
        fallback_tier: "optional",
        reason: "زدنا مصاريف الدار حيث قلتي كاين حتى جزء آخر من المساهمة.",
        objective_bias_effect: "خليّناها اختيارية باش ما نكثروش التفصيل إلا ما كنتيش باغيه.",
      });
    }

    if (detailedMode && contributionTypes.has("bills")) {
      entries.push({
        name: "Factures",
        group_key: "bills",
        kind: "spend",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "لفواتير دخلات هنا حيث المساهمة ديالك فيها جزء واضح ديال الفواتير.",
        objective_bias_effect: "بانات فالمعاينة باش التنظيم يكون أقرب للواقع.",
      });
    }

    if (detailedMode && contributionTypes.has("food")) {
      entries.push({
        name: "Nourriture",
        group_key: "essentials",
        kind: "spend",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "المساهمة ديالك فالدار فيها حتى الماكلة، لذلك خلّيناها باينة فالأظرفة من الأول.",
        objective_bias_effect: "هاد المعطى كيخلي المصاريف اليومية أقرب للواقع بلا ما نقسمو المبلغ من جديد.",
      });
    }

    return entries;
  }

  return [];
}

function resolveMixedTransportDetailTarget(answers: Answers): string | null {
  const primaryMode = getString(answers, "TRX1_primary_mode");
  if (primaryMode === "equal") return getString(answers, "TRX4_equal_detail_target");
  return primaryMode || null;
}

function getTransportProposalEntries(
  answers: Answers,
  _namingStyle: ObjectivePolicy["naming_style"]
): HousingProposalEntry[] {
  const transport = getString(answers, "E4_transport_mode");
  if (!transport) return [];

  const granularity = getEnvelopeGranularity(answers);
  const simpleMode = granularity === "simple";
  const mixedDetailed = transport === "mixed" && getString(answers, "TRX3_detail_mode") === "detailed";
  const detailedMode = granularity === "detailed" || mixedDetailed;

  const buildPublicEntries = (): HousingProposalEntry[] => {
    if (simpleMode) {
      return [
        {
          name: "Transport",
          group_key: "transport",
          kind: "spend",
          source: "suggested",
          fallback_tier: "core",
          reason: "خلّيناه ظرف واحد بسيط باش مصاريف التنقل تبان بلا تعقيد.",
          objective_bias_effect: "هاد الشكل مناسب إلا كنت باغي التنظيم يبقى خفيف وواضح.",
        },
      ];
    }

    const entries: HousingProposalEntry[] = [
      {
        name: "Transport public",
        group_key: "transport",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: "النقل العمومي هو المصروف الرئيسي هنا، لذلك عطيناه ظرف واضح بوحدو.",
        objective_bias_effect: "وضحناه بالاسم ديالو باش تعرف شنو داخل فالتنقل بالضبط.",
      },
    ];

    const hasTaxiAmount =
      getString(answers, "TRP1_taxi_usage") === "yes" ||
      getString(answers, "TRX_P_taxi_usage") === "yes" ||
      toNumber(getString(answers, "TRP1_taxi_monthly_amount")) > 0 ||
      toNumber(getString(answers, "TRX_P_taxi_monthly_amount")) > 0;
    if (hasTaxiAmount) {
      entries.push({
        name: "Taxi / VTC",
        group_key: "transport",
        kind: "spend",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "الطاكسي أو التطبيقات بان ليهم مبلغ واضح، لذلك خرجناهم بوحدهم باش ما يذوبوش وسط النقل العمومي.",
        objective_bias_effect: "كيعاونك تشوف الفرق بين النقل العمومي والمشاوير اللي كتطلع بأثمنة متغيرة.",
      });
    }

    return entries;
  };

  const buildCarEntries = (): HousingProposalEntry[] => {
    if (simpleMode && !detailedMode) {
      return [
        {
          name: "Transport",
          group_key: "transport",
          kind: "spend",
          source: "suggested",
          fallback_tier: "core",
          reason: "جمعنا مصاريف الطوموبيل فظرف واحد باش التنظيم يبقى بسيط.",
          objective_bias_effect: "مناسب إلا كنت باغي غير صورة واضحة بلا تفصيل بزاف.",
        },
      ];
    }

    const entries: HousingProposalEntry[] = [
      {
        name: "Carburant",
        group_key: "transport",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: "المازوط كيبقى المصروف اليومي الأوضح فالطوموبيل، لذلك خاصو يبان بوحدو.",
        objective_bias_effect: "طلعناه للأول حيث كيتكرر أكثر من باقي مصاريف الطوموبيل.",
      },
      {
        name: "Assurance auto",
        group_key: "transport",
        kind: "accumulating",
        source: "suggested",
        fallback_tier: detailedMode ? "recommended" : "core",
        reason: "تأمين الطوموبيل حاضر فالأجوبة، لذلك خليه ظاهر حتى إلا كان كيتخلص بدورية مختلفة.",
        objective_bias_effect: "فصلناه باش المصاريف الدورية ما تضيعش.",
      },
      {
        name: "Entretien auto",
        group_key: "transport",
        kind: "accumulating",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "صيانة الطوموبيل مفيدة إلا بغيت تفصل المصاريف اللي كتجمع مع الوقت.",
        objective_bias_effect: "خليّناها مستقلة باش الإصلاحات ما تخلطش مع المازوط.",
      },
    ];

    const hasAnyCarParking = getCarTransportPrefixes(answers).some(
      (prefix) => getString(answers, `${prefix}car_parking`) === "yes"
    );
    if (detailedMode && hasAnyCarParking) {
      entries.push({
        name: "Parking",
        group_key: "transport",
        kind: "spend",
        source: "suggested",
        fallback_tier: "optional",
        reason: "الباركينغ بان فالأجوبة، لذلك ظهرناه غير فالوضع المفصل.",
        objective_bias_effect: "بقيناه اختياري باش ما نكثروش الأظرفة إلا ما كانش مهم ليك.",
      });
    }

    const hasAnyCarLoan = getCarTransportPrefixes(answers).some(
      (prefix) =>
        getString(answers, `${prefix}car_loan`) === "yes" ||
        toNumber(getString(answers, `${prefix}car_loan_amount`)) > 0
    );
    if (hasAnyCarLoan) {
      entries.push({
        name: "Crédit auto",
        group_key: "transport",
        kind: "spend",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "قرض الطوموبيل بان كمصروف ثابت، لذلك خاصو يبان بوحدو باش ما يتخلطش مع باقي التنقل.",
        objective_bias_effect: "كيخلي الضغط الحقيقي ديال المركبة باين بوضوح من الأول.",
      });
    }

    const hasAnyInspection = getCarTransportPrefixes(answers).some(
      (prefix) =>
        getString(answers, `${prefix}car_inspection`) === "yes" ||
        toNumber(getString(answers, `${prefix}car_inspection_amount`)) > 0
    );
    if (hasAnyInspection) {
      entries.push({
        name: "Contrôle technique",
        group_key: "transport",
        kind: "accumulating",
        source: "suggested",
        fallback_tier: detailedMode ? "recommended" : "optional",
        reason: "الفحص التقني كيتعاود بدورية معروفة، لذلك خرجناه بوحدو باش يبقى حاضر فالتخطيط.",
        objective_bias_effect: "كيمنع هاد المصروف الدوري يطيح عليك دفعة وحدة بلا ما يكون محسوب.",
      });
    }

    const hasAnyTax = getCarTransportPrefixes(answers).some(
      (prefix) =>
        getString(answers, `${prefix}car_tax`) === "yes" ||
        toNumber(getString(answers, `${prefix}car_tax_annual_amount`)) > 0
    );
    if (hasAnyTax) {
      entries.push({
        name: "Taxe auto",
        group_key: "transport",
        kind: "accumulating",
        source: "suggested",
        fallback_tier: detailedMode ? "recommended" : "optional",
        reason: "ضريبة الطوموبيل مصروف معروف كيرجع كل عام، لذلك خرجناها بوحدها باش تبقى محسوبة.",
        objective_bias_effect: "هاد الفصل كيعاونك تميّز بين اليومي وبين المصاريف السنوية ديال المركبة.",
      });
    }

    return entries;
  };

  const buildMotorbikeEntries = (): HousingProposalEntry[] => {
    if (simpleMode && !detailedMode) {
      return [
        {
          name: "Transport",
          group_key: "transport",
          kind: "spend",
          source: "suggested",
          fallback_tier: "core",
          reason: "جمعنا مصاريف الموطور فظرف واحد حيث بغيتي التنظيم يبقى ساهل.",
          objective_bias_effect: "هاد الشكل مناسب إلا كنت باغي غير صورة سريعة على التنقل.",
        },
      ];
    }

    const entries: HousingProposalEntry[] = [
      {
        name: "Carburant 2 roues",
        group_key: "transport",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: "مازوط الموطور كيبقى المصروف الرئيسي المتكرر، لذلك بان بوحدو.",
        objective_bias_effect: "خلّيناه واضح باش تعرف تأثير التنقل اليومي على الميزانية.",
      },
    ];

    const hasBikeInsurance = getBikeTransportPrefixes(answers).some(
      (prefix) =>
        toNumber(getString(answers, `${prefix}bike_insurance_amount`)) > 0 ||
        getString(answers, `${prefix}bike_insurance_cycle`) !== ""
    );
    if (hasBikeInsurance) {
      entries.push({
        name: "Assurance 2 roues",
        group_key: "transport",
        kind: "accumulating",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "تأمين الموطور بان كمصروف دوري، لذلك خرجناه بوحدو باش يبقى ظاهر.",
        objective_bias_effect: "كيخلي مصاريف المركبة الصغيرة ما تضيعش وسط الوقود فقط.",
      });
    }

    entries.push({
      name: "Entretien 2 roues",
      group_key: "transport",
      kind: "accumulating",
      source: "suggested",
      fallback_tier: "recommended",
      reason: "صيانة الموطور مفيدة إلا بغيت تفرق المصاريف اللي كتجي على فترات.",
      objective_bias_effect: "بقينا ما مفصلينش أكثر من اللازم باش اللائحة تبقى خفيفة.",
    });

    return entries;
  };

  if (transport === "public") return buildPublicEntries();
  if (transport === "car") return buildCarEntries();
  if (transport === "motorbike") return buildMotorbikeEntries();

  if (transport === "mixed") {
    if (!mixedDetailed || simpleMode) {
      return [
        {
          name: "Transport",
          group_key: "transport",
          kind: "spend",
          source: "suggested",
          fallback_tier: "core",
          reason: "حيت التنقل عندك مختلط، بدينا بظرف واحد بسيط يضم المصاريف كاملين.",
          objective_bias_effect: "كنخليوه بسيط إلا ما طلبتيش التفصيل صراحة.",
        },
      ];
    }

    const detailTarget = resolveMixedTransportDetailTarget(answers);
    if (detailTarget === "public" || detailTarget === "public_more") return buildPublicEntries();
    if (detailTarget === "car" || detailTarget === "car_more") return buildCarEntries();
    if (detailTarget === "bike" || detailTarget === "bike_more") return buildMotorbikeEntries();
  }

  return [
    {
      name: "Transport",
      group_key: "transport",
      kind: "spend",
      source: "suggested",
      fallback_tier: "core",
      reason: "بقيناه ظرف عام حتى تتوضح أكثر طريقة التنقل اللي كتعتمد عليها.",
      objective_bias_effect: "غادي يتفصل أكثر ملي تبان الصورة كاملة ديال التنقل.",
    },
  ];
}

function getLifestyleProposalEntries(
  answers: Answers,
  policy: ObjectivePolicy
): HousingProposalEntry[] {
  const lifestyle = getString(answers, "E7_lifestyle") || "high";

  const granularity = getEnvelopeGranularity(answers);
  const simpleMode = granularity === "simple";

  if (lifestyle === "low") {
    return [
      {
        name: "Loisirs",
        group_key: "lifestyle",
        kind: "spend",
        source: "suggested",
        fallback_tier: "optional",
        reason: "بغيت مستوى معيشة هادئ، لذلك خلّيناه ظرف صغير وواضح.",
        objective_bias_effect: "بقى حاضر بشكل خفيف باش ما يزاحمش الضروريات.",
      },
    ];
  }

  const entries: HousingProposalEntry[] = [
    {
      name: "Loisirs",
      group_key: "lifestyle",
      kind: "spend",
      source: "suggested",
      fallback_tier: "optional",
      reason: "تزاد حسب المستوى ديال المعيشة اللي اخترتي.",
      objective_bias_effect: "بداينا بالأبسط باش يبقى lifestyle حاضر بلا تضخيم.",
    },
  ];

  if (lifestyle === "high" || !simpleMode) {
    entries.push({
      name: "Restaurants",
      group_key: "lifestyle",
      kind: "spend",
      source: "suggested",
      fallback_tier: "optional",
        reason: "زدناه حيث مستوى المعيشة متوسط أو عالي وكيبان فيه خرجات ومطاعم.",
      objective_bias_effect: "بقيناه ثانوي ومتوازن باش ما يضغطش على الأساسيات.",
    });
  }

  if (lifestyle === "high" && !simpleMode) {
    entries.push({
      name: "Shopping",
      group_key: "lifestyle",
      kind: "spend",
      source: "suggested",
      fallback_tier: "optional",
      reason: "زيدناه ملي اخترتي مستوى معيشة مريح باش يبان هاد الجزء بوحدو.",
      objective_bias_effect: "بقيناه متدرج باش يبان الفرق بلا ما يتنفخ عدد الأظرفة بزاف.",
    });
  }

  return entries;
}

function getGoalPreviewName(
  goalName: string,
  answers: Answers,
  namingStyle: ObjectivePolicy["naming_style"],
  index = 1,
  totalGoals = 1
): string {
  const granularity = getEnvelopeGranularity(answers);
  const simpleMode = granularity === "simple" || namingStyle === "generic";
  const normalizedGoalName = normalizeTextInput(goalName);
  if (!normalizedGoalName) return totalGoals > 1 ? `Objectif ${index}` : simpleMode ? "Objectif principal" : "Objectif";
  if (simpleMode) return totalGoals > 1 ? `Objectif ${index}` : "Objectif principal";
  if (granularity === "balanced") {
    const shortened = normalizedGoalName.length > 28 ? `${normalizedGoalName.slice(0, 28).trim()}...` : normalizedGoalName;
    return `Objectif — ${shortened}`;
  }
  return `Objectif — ${normalizedGoalName}`;
}

function buildGoalRealityCheckForEntry(
  entry: {
    target_amount: number;
    current_amount?: number;
    target_date?: string | null;
  },
  answers: Answers
): GoalRealityCheck {
  const sanity = computeSanity(answers);
  const amount = Math.max(0, roundAmount((entry.target_amount || 0) - (entry.current_amount || 0)));
  const realisticMonthlyCap = getRealisticGoalMonthlyCapFromSanity(sanity);
  const goalDate = entry.target_date || null;

  if (!amount || amount <= 0 || !sanity.incomeEstimate || sanity.incomeEstimate <= 0 || realisticMonthlyCap === null) {
    return {
      status: "unknown",
      amount,
      months_to_goal: null,
      required_monthly: null,
      realistic_monthly_cap: realisticMonthlyCap,
      suggested_amount_by_date: null,
      estimated_months_needed: null,
    };
  }

  if (!goalDate) {
    const estimatedMonthsNeeded = realisticMonthlyCap > 0 ? Math.ceil(amount / realisticMonthlyCap) : null;
    const veryLargeWithoutDate = realisticMonthlyCap > 0 && amount > realisticMonthlyCap * 240;
    return {
      status: veryLargeWithoutDate ? "no_date" : "unknown",
      amount,
      months_to_goal: null,
      required_monthly: null,
      realistic_monthly_cap: realisticMonthlyCap,
      suggested_amount_by_date: null,
      estimated_months_needed: estimatedMonthsNeeded,
    };
  }

  const monthsToGoal = getMonthsUntilGoal(goalDate);
  if (!monthsToGoal || monthsToGoal <= 0) {
    return {
      status: "unknown",
      amount,
      months_to_goal: monthsToGoal,
      required_monthly: null,
      realistic_monthly_cap: realisticMonthlyCap,
      suggested_amount_by_date: null,
      estimated_months_needed: null,
    };
  }

  const requiredMonthly = roundAmount(amount / monthsToGoal);
  const suggestedAmountByDate = roundAmount(realisticMonthlyCap * monthsToGoal);
  const estimatedMonthsNeeded =
    realisticMonthlyCap > 0 ? Math.ceil(amount / realisticMonthlyCap) : null;

  let status: GoalRealityStatus = "realistic";
  if (requiredMonthly > realisticMonthlyCap * 3) {
    status = "impossible_now";
  } else if (requiredMonthly > realisticMonthlyCap * 1.5) {
    status = "unrealistic";
  } else if (requiredMonthly > realisticMonthlyCap) {
    status = "ambitious";
  }

  return {
    status,
    amount,
    months_to_goal: monthsToGoal,
    required_monthly: requiredMonthly,
    realistic_monthly_cap: realisticMonthlyCap,
    suggested_amount_by_date: suggestedAmountByDate,
    estimated_months_needed: estimatedMonthsNeeded,
  };
}

function getGoalProposalEntries(
  answers: Answers,
  policy: ObjectivePolicy,
  salaryAmountEffects: SalaryAmountEffects | null
): HousingProposalEntry[] {
  const goals = getGoalBuilderEntries(answers);
  if (goals.length === 0) return [];

  const granularity = getEnvelopeGranularity(answers);
  const simpleMode = granularity === "simple" || policy.naming_style === "generic";
  return goals.map((goalEntry, index) => {
    const visibleName = getGoalPreviewName(
      goalEntry.name,
      answers,
      policy.naming_style,
      index + 1,
      goals.length
    );
    const amountLabel = goalEntry.target_amount > 0 ? formatMad(goalEntry.target_amount) : null;
    const dateLabel = goalEntry.target_date ? formatPreviewDate(goalEntry.target_date) : null;
    const goalReality = buildGoalRealityCheckForEntry(goalEntry, answers);

    const reasonParts = ["الهدف بقى حاضر فالمعاينة باش يبان قدّامك من دابا."];
    if (simpleMode) {
      reasonParts.push("بقيناه باسم بسيط باش ما نكثروش عليك الأظرفة.");
    } else {
      reasonParts.push(`سمّيناه باسم "${goalEntry.name}" باش يبقى واضح شنو باغي توصل ليه.`);
    }
    if (amountLabel) {
      reasonParts.push(`المبلغ المستهدف هنا هو ${amountLabel}.`);
    }
    if (goalEntry.current_amount > 0) {
      reasonParts.push(`ومجموع دابا فيه ${formatMad(goalEntry.current_amount)}.`);
    }
    if (dateLabel && granularity !== "simple") {
      reasonParts.push(`والتاريخ اللي حطيتي هو ${dateLabel}.`);
    }
    if (goalReality.status === "ambitious" && goalReality.required_monthly) {
      reasonParts.push(`هاد الهدف طالع شوية على الإمكانية الحالية حيث خاص تقريباً ${formatMad(goalReality.required_monthly)} فالشهر.`);
    } else if (
      (goalReality.status === "unrealistic" || goalReality.status === "impossible_now") &&
      goalReality.realistic_monthly_cap
    ) {
      reasonParts.push(`فهاد المدة الهدف باين كبير على الوضعية الحالية، والواقعي دابا أقرب لـ ${formatMad(goalReality.realistic_monthly_cap)} فالشهر.`);
    }

    let objectiveBiasEffect = "خلّيناه ظاهر باش يبقى الهدف حاضر وسط باقي الأظرفة.";
    if (policy.mode === "save") {
      objectiveBiasEffect = "طلعناه وبان بشكل أوضح حيث الهدف كيمشي مع منطق التوفير.";
    } else if (policy.mode === "organize" && simpleMode) {
      objectiveBiasEffect = "بقيناه خفيف وواضح باش ما يزاحمش التنظيم الأساسي.";
    } else if (policy.mode === "debt") {
      objectiveBiasEffect = "خلّيناه حاضر ولكن ما طلعناهش فوق الديون والضروريات.";
    }

    if (salaryAmountEffects?.pressure_level === "tight" && salaryAmountEffects.realistic_goal_monthly_cap) {
      objectiveBiasEffect = `${objectiveBiasEffect} وخلاه محافظ دابا حيث السقف الواقعي تقريباً هو ${formatMad(
        salaryAmountEffects.realistic_goal_monthly_cap
      )} فالشهر.`;
    }

    return {
      name: visibleName,
      group_key: "goals",
      kind: "goal",
      source: "suggested",
      fallback_tier:
        policy.mode === "save" && salaryAmountEffects?.pressure_level !== "tight"
          ? "core"
          : goalEntry.importance === "critical"
          ? "core"
          : "recommended",
      reason: reasonParts.join(" "),
      objective_bias_effect: objectiveBiasEffect,
    };
  });
}

function getProposalTierForDomain(
  policy: ObjectivePolicy,
  domain: EnvelopeProposalDomain,
  fallback: EnvelopeProposalTier = "recommended"
): EnvelopeProposalTier {
  if (policy.mode === "organize") {
    if (["essentials", "housing", "transport", "bills", "buffer"].includes(domain)) return "core";
    if (["family", "goals", "debts"].includes(domain)) return "recommended";
    return "optional";
  }
  if (policy.mode === "save") {
    if (["essentials", "housing", "transport", "bills", "buffer", "saving"].includes(domain)) return "core";
    if (["family", "goals", "debts"].includes(domain)) return "recommended";
    return "optional";
  }
  if (policy.mode === "debt") {
    if (["essentials", "housing", "transport", "bills", "debts", "buffer"].includes(domain)) return "core";
    if (["family", "goals"].includes(domain)) return "recommended";
    return "optional";
  }
  if (["essentials", "housing", "transport", "bills", "buffer"].includes(domain)) return "core";
  if (["saving", "family", "debts", "goals"].includes(domain)) return "recommended";
  return fallback;
}

function shouldDefaultIncludeProposal(policy: ObjectivePolicy, tier: EnvelopeProposalTier): boolean {
  return policy.auto_include_tiers.includes(tier);
}

function getDefaultRolloverForProposal(
  policy: ObjectivePolicy,
  kind: "buffer" | "saving" | "goal" | "accumulating" | "spend"
): boolean {
  if (kind === "buffer") return true;
  if (kind === "goal") return true;
  if (kind === "saving") return policy.mode === "save" || policy.mode === "balanced";
  if (kind === "accumulating") return policy.mode === "save" || policy.mode === "balanced";
  return false;
}

function getSmartRolloverRecommendationForProposal(
  answers: Answers,
  policy: ObjectivePolicy,
  salaryAmountEffects: SalaryAmountEffects | null,
  candidate: {
    name: string;
    group_key: EnvelopeProposalDomain;
    kind: "buffer" | "saving" | "goal" | "accumulating" | "spend";
  }
): { enabled: boolean; label: string; reason: string } {
  const fallbackEnabled = getDefaultRolloverForProposal(policy, candidate.kind);
  const cadence = getIncomeCadenceForRecurringCosts(answers);
  const normalizedName = slugify(candidate.name);
  const pressure = salaryAmountEffects?.pressure_level ?? null;
  const debtExtraEnabled = getString(answers, "D8_debt_extra_monthly") === "yes";
  const ownerMaintenanceSaving = getString(answers, "HSN4_maintenance_saving") === "yes";
  const lifestyle = getString(answers, "E7_lifestyle");
  const kidsCount = getResolvedKidsCount(answers);
  const schoolPaymentCycle = getString(answers, "E0f_school_payment_cycle");
  const carInsuranceCycle =
    normalizedName.includes("assurance-auto")
      ? getString(answers, "TR1_car_insurance_cycle") || getString(answers, "TRX_C_car_insurance_cycle")
      : "";
  const isHealthEnvelope =
    normalizedName.includes("sante") ||
    normalizedName.includes("pharm") ||
    normalizedName.includes("medic") ||
    normalizedName.includes("medec") ||
    normalizedName.includes("clinique") ||
    normalizedName.includes("analyse") ||
    normalizedName.includes("soin") ||
    normalizedName.includes("dentaire") ||
    normalizedName.includes("lunette");
  const isFoodEnvelope =
    normalizedName.includes("nourriture") ||
    normalizedName.includes("course") ||
    normalizedName.includes("epicerie") ||
    normalizedName.includes("restauration") ||
    normalizedName.includes("restaurant") ||
    normalizedName.includes("makla");
  const isEducationEnvelope =
    normalizedName.includes("ecole") ||
    normalizedName.includes("hadana") ||
    normalizedName.includes("fourniture") ||
    normalizedName.includes("cours") ||
    normalizedName.includes("soutien");
  const isDailyTransportEnvelope =
    normalizedName.includes("carburant") ||
    normalizedName === "transport" ||
    normalizedName.includes("transport-public") ||
    normalizedName.includes("parking");

  const recommendOn = (reason: string, label = "موصى به") => ({
    enabled: true,
    label,
    reason,
  });

  const recommendOff = (reason: string, label = "غالباً مطفّي") => ({
    enabled: false,
    label,
    reason,
  });

  if (candidate.group_key === "buffer") {
    return recommendOn("هاد الظرف خاصو يبقى كيتجمع باش يبقى الاحتياط حاضر.", "موصى به بقوة");
  }
  if (candidate.group_key === "saving") {
    return recommendOn("هاد الظرف ديال تجميع، لذلك الأفضل يخلي الباقي يتراكم.", "موصى به بقوة");
  }
  if (candidate.group_key === "goals" || candidate.kind === "goal") {
    return recommendOn("الهدف خاصو يتجمع مع الوقت، لذلك الأفضل يبقى مفعّل.", "موصى به بقوة");
  }
  if (candidate.kind === "accumulating") {
    return recommendOn("هاد المصروف ماشي يومي وكيحتاج يتجمع على أكثر من دورة دخل.");
  }

  if (
    normalizedName.includes("loyer") ||
    normalizedName.includes("credit-logement") ||
    normalizedName.includes("contribution-famille")
  ) {
    if (cadence === "monthly") {
      return recommendOff("هاد المصروف غالباً كيتخلص مع نفس الدورة الشهرية، ماشي ضروري يحتافظ بالباقي.");
    }
    return recommendOn("حيت الدخل ديالك كيتقسم على أكثر من دفعة، الاحتفاظ بالباقي كيعاونك تجمع حتى يجي وقت الأداء.");
  }

  if (candidate.group_key === "bills") {
    if (cadence === "monthly") {
      return recommendOff("لفواتير غالباً كتتصفى مع نفس الدورة، لذلك غالباً ماشي ضروري.");
    }
    return recommendOn("الدخل الجاي قبل وقت بعض الفواتير، لذلك الاحتفاظ بالباقي كيعاونك تجمعهم.");
  }

  if (candidate.group_key === "debts") {
    if (debtExtraEnabled || cadence !== "monthly") {
      return recommendOn("إلا بغيتي تجمع للأداء أو تزيد دفعة إضافية، الأفضل تخليه مفعّل.");
    }
    return recommendOff("إلى كان غير القسط الشهري العادي، غالباً ماشي ضروري يحتافظ بالباقي.");
  }

  if (candidate.group_key === "family") {
    if (isEducationEnvelope) {
      if (schoolPaymentCycle === "annual") {
        return recommendOn("مصروف المدرسة سنوي، لذلك الأفضل يبقى كيتجمع من دابا.", "موصى به بقوة");
      }
      if (schoolPaymentCycle === "quarterly") {
        return recommendOn("مصروف المدرسة كيتخلص كل 3 شهور، لذلك الأفضل يبقى مفعّل باش يتجمع تدريجياً.");
      }
      if (schoolPaymentCycle === "monthly") {
        return cadence === "monthly"
          ? recommendOff("إلى المدرسة كتتخلص شهرياً مع نفس الدورة، غالباً ماشي ضروري يحتافظ بالباقي.")
          : recommendOn("حتى إلا كانت المدرسة شهرية، الدخل المتقسم كيخلي التجميع مفيد.");
      }
      if (kidsCount > 0 && cadence === "monthly") {
        return recommendOn("مصاريف المدرسة والحضانة كتطلع على دفعات ومواسم، لذلك الأفضل يبقى مفعّل.");
      }
      if (cadence !== "monthly") {
        return recommendOn("حيت هاد المصروف غالباً شهري والدخل ديالك متقسم، الأفضل تخليه يتجمع.");
      }
      return recommendOff("إلى كان الأداء شهري وواضح، غالباً ماشي ضروري يحتافظ بالباقي.");
    }
    return recommendOff("المساعدة العائلية غالباً كتخرج مع نفس الدورة، لذلك غالباً خليها مطفّية.");
  }

  if (candidate.group_key === "transport") {
    if (normalizedName.includes("assurance-auto")) {
      if (carInsuranceCycle === "annual" || carInsuranceCycle === "semiannual" || carInsuranceCycle === "quarterly") {
        return recommendOn("التأمين ماشي كل دورة، لذلك الأفضل تخليه يتجمع حتى يجي وقتو.", "موصى به بقوة");
      }
      return cadence === "monthly"
        ? recommendOff("إلى كان التأمين كيتخلص شهرياً، غالباً ماشي ضروري.")
        : recommendOn("بما أن الدخل ديالك متقسم، الاحتفاظ بالباقي كيعاونك تجمع للتأمين.");
    }
    if (normalizedName.includes("entretien-auto") || normalizedName.includes("entretien-2-roues")) {
      return recommendOn("الصيانة كتجي على فترات، لذلك الأحسن يتجمع الباقي فيها.");
    }
    if (isDailyTransportEnvelope) {
      return recommendOff("هاد مصروف جاري ومتكرر، غالباً خليه مطفّي باش يبقى واضح كل دورة بوحدها.");
    }
  }

  if (candidate.group_key === "housing") {
    if (normalizedName.includes("entretien-maison")) {
      return recommendOn(
        ownerMaintenanceSaving
          ? "بما أنك قلتي كتجمع للصيانة، الأفضل يبقى مفعّل."
          : "الصيانة كتحتاج تجميع مع الوقت، لذلك الأفضل يبقى مفعّل."
      );
    }
    if (normalizedName.includes("impots")) {
      return recommendOn("الضرايب ماشي مصروف كل دورة، لذلك الاحتفاظ بالباقي كيناسبها.");
    }
    if (normalizedName === "maison" || normalizedName.includes("charges")) {
      return cadence !== "monthly"
        ? recommendOn("هاد المصاريف السكنية كتحتاج تجمع بين الدفعات إذا كان الدخل متقسم.")
        : recommendOff("إلى السكن كيتدار فالدورة نفسها، غالباً خليه مطفّي.");
    }
  }

  if (candidate.group_key === "essentials") {
    if (isHealthEnvelope) {
      return recommendOn(
        pressure === "tight"
          ? "حتى مع الضغط الحالي، الصحة مصروف غير منتظم وقد يطلع فجأة، لذلك الأفضل يبقى مفعّل."
          : "الصحة ماشي مصروف يومي ثابت، والأفضل يبقى مفعّل باش يتجمع الباقي للمفاجآت."
      );
    }
    if (isFoodEnvelope) {
      return recommendOff("الماكلة والمصاريف اليومية أوضح إلا كان كل دورة دخل بوحدها.");
    }
    if (lifestyle === "calm" && pressure === "tight") {
      return recommendOff("هاد المصروف الأساسي خليه مطفّي دابا باش تبقى القراءة الشهرية أوضح.");
    }
    return recommendOff("المصاريف اليومية كيبانوا أوضح إلا كانت كل دورة بوحدها.");
  }

  if (candidate.group_key === "lifestyle") {
    return recommendOff(
      pressure === "tight"
        ? "مع الضغط الحالي، الأفضل ما تخليش هاد المصروف يتجمع."
        : "هاد المصروف اختياري، وغالباً أوضح إلا كان كل دورة بوحدها."
    );
  }

  if (fallbackEnabled) {
    return recommendOn("هاد الظرف كيبان من النوع اللي كيتجمع مع الوقت.");
  }
  return recommendOff("غالباً أوضح ليك إلا بقى كل دورة دخل بوحدها.");
}

function addProposalCandidate(
  candidates: EnvelopeProposalCandidate[],
  candidate: Omit<EnvelopeProposalCandidate, "id" | "group_label" | "core">,
  reasons: Map<string, string[]>
) {
  const normalizedName = normalizeProposalName(candidate.name);
  if (!normalizedName || isSystemProposalName(normalizedName)) return;

  const baseId = `${candidate.group_key}:${slugify(normalizedName)}`;
  const existing = candidates.find((item) => item.id === baseId);
  if (existing) {
    if (getProposalTierRank(candidate.tier) < getProposalTierRank(existing.tier)) {
      existing.tier = candidate.tier;
      existing.core = candidate.tier === "core";
    } else if (existing.tier === "core") {
      existing.core = true;
    }
    const previousRolloverEnabled = existing.rollover_enabled;
    existing.rollover_enabled = existing.rollover_enabled || candidate.rollover_enabled;
    if (!previousRolloverEnabled && candidate.rollover_enabled) {
      existing.rollover_recommendation_label = candidate.rollover_recommendation_label;
      existing.rollover_recommendation_reason = candidate.rollover_recommendation_reason;
    }
    existing.default_included = existing.default_included || candidate.default_included;
    if (existing.source !== "baseline" && candidate.source === "baseline") {
      existing.source = "baseline";
    }
    const mergedReasons = reasons.get(baseId) ?? [existing.reason];
    mergedReasons.push(candidate.reason);
    const deduped = Array.from(new Set(mergedReasons.filter(Boolean)));
    reasons.set(baseId, deduped);
    existing.reason = deduped.join(" · ");
    existing.objective_bias_effect = Array.from(
      new Set([existing.objective_bias_effect, candidate.objective_bias_effect].filter(Boolean))
    ).join(" · ");
    return;
  }

  const dedupedReasons = Array.from(new Set([candidate.reason].filter(Boolean)));
  reasons.set(baseId, dedupedReasons);
  candidates.push({
    id: baseId,
    name: normalizedName,
    group_key: candidate.group_key,
    group_label: PROPOSAL_DOMAIN_LABELS[candidate.group_key],
    rollover_enabled: candidate.rollover_enabled,
    rollover_recommendation_label: candidate.rollover_recommendation_label,
    rollover_recommendation_reason: candidate.rollover_recommendation_reason,
    tier: candidate.tier,
    core: candidate.tier === "core",
    default_included: candidate.default_included,
    reason: dedupedReasons.join(" · "),
    objective_bias_effect: candidate.objective_bias_effect,
    source: candidate.source,
  });
}

function buildEnvelopeProposalSignals(
  answers: Answers,
  derivedEnvelopes: string[],
  validatedSuggestions: string[],
  salaryAmountEffects: SalaryAmountEffects | null
): EnvelopeProposalSignals {
  return {
    objective_values: getList(answers, "Q0b_primary_objective"),
    income_type: getString(answers, "Q0_income_type"),
    monthly_income_estimate: salaryAmountEffects?.monthly_income_estimate ?? null,
    salary_pressure_level: salaryAmountEffects?.pressure_level ?? null,
    salary_income_band: salaryAmountEffects?.income_band ?? null,
    remaining_after_goals: salaryAmountEffects?.remaining_after_goals ?? null,
    housing_status: getString(answers, "E3_housing_status"),
    transport_mode: getString(answers, "E4_transport_mode"),
    transport_detail_mode: getString(answers, "TRX3_detail_mode"),
    has_debt: getString(answers, "E5_has_debt") === "yes",
    has_goal: getString(answers, "G0_has_goal") === "yes",
    lifestyle: getString(answers, "E7_lifestyle"),
    supports_family: getString(answers, "E6_support_family") === "yes",
    kids_count: getResolvedKidsCount(answers),
    fixed_items: getList(answers, "FX1_fixed_items"),
    validated_suggestions: validatedSuggestions,
    derived_envelopes: derivedEnvelopes,
  };
}

function buildEnvelopeProposalCandidates(
  answers: Answers,
  objectivePolicy: ObjectivePolicy,
  salaryAmountEffects: SalaryAmountEffects | null
): EnvelopeProposalCandidate[] {
  const candidates: EnvelopeProposalCandidate[] = [];
  const reasons = new Map<string, string[]>();
  const guidanceSnapshot = getGuidanceDirectionSnapshot(answers);
  const housingEntries = getHousingProposalEntries(answers, objectivePolicy.naming_style);
  const transportEntries = getTransportProposalEntries(answers, objectivePolicy.naming_style);
  const debtEntries = getDebtProposalEntries(answers, objectivePolicy.naming_style);
  const familyEntries = getFamilyProposalEntries(answers, objectivePolicy.naming_style);
  const fixedItemEntries = getFixedItemProposalEntries(answers, objectivePolicy.naming_style);
  const goalEntries = getGoalProposalEntries(answers, objectivePolicy, salaryAmountEffects);
  const lifestyleEntries = getLifestyleProposalEntries(answers, objectivePolicy);
  const salaryPressure = salaryAmountEffects?.pressure_level ?? null;
  const salaryTight = salaryPressure === "tight";
  const salaryComfortable = salaryPressure === "comfortable";
  const lifestyleChoice = getString(answers, "E7_lifestyle");
  const lifestyleFundableFromPlan = getString(answers, "F1_lifestyle_fundable") !== "no";
  const guidanceMode = guidanceSnapshot?.mode ?? null;
  const guidancePrioritizesDebt = guidanceMode === "debt_relief_first";
  const guidancePrioritizesSafety = guidanceMode === "stability_first";
  const guidancePrioritizesGoals = guidanceMode === "goal_growth_first";
  const guidanceKeepsSafety =
    guidanceSnapshot ? guidanceSnapshot.keep_safety && guidanceSnapshot.planned_reserve > 0 : true;
  const guidanceKeepsFlex =
    guidanceSnapshot ? guidanceSnapshot.keep_flex && guidanceSnapshot.planned_flex > 0 : true;
  const shouldIncludeKnownFixedProposal = (name: string, fallback: boolean): boolean => {
    const knownAmount = getKnownProposalAmount(name, answers);
    return typeof knownAmount === "number" && knownAmount > 0 ? true : fallback;
  };
  const withSmartRollover = <
    const T extends {
      name: string;
      group_key: EnvelopeProposalDomain;
      kind: "buffer" | "saving" | "goal" | "accumulating" | "spend";
    },
  >(
    draft: T
  ): T & {
    rollover_enabled: boolean;
    rollover_recommendation_label: string;
    rollover_recommendation_reason: string;
  } => {
    const recommendation = getSmartRolloverRecommendationForProposal(
      answers,
      objectivePolicy,
      salaryAmountEffects,
      draft
    );
    return {
      ...draft,
      rollover_enabled: recommendation.enabled,
      rollover_recommendation_label: recommendation.label,
      rollover_recommendation_reason: recommendation.reason,
    };
  };

  addProposalCandidate(
    candidates,
    withSmartRollover({
      name: "Imprévus / طوارئ",
      group_key: "buffer",
      tier: guidanceKeepsSafety
        ? getProposalTierForDomain(
            objectivePolicy,
            "buffer",
            guidancePrioritizesDebt ? "recommended" : "core"
          )
        : "optional",
      default_included: guidanceKeepsSafety,
      reason: guidanceKeepsSafety
        ? "Toujours proposé comme buffer de sécurité pour absorber les écarts."
        : "خليّناه اختياري حيث التوجيه اللي قبل اختار ما يحجزش مبلغ مستقل للأمان دابا.",
      objective_bias_effect:
        !guidanceKeepsSafety
          ? "ما تفعّلش تلقائياً حيث فالتوجيه اخترنا نخليو المبلغ يمشي لأولويات أخرى دابا."
          : objectivePolicy.mode === "debt"
          ? "خليّناه حاضر ولكن بحجم صغير باش ما يضيعش التركيز على الديون."
          : salaryTight
          ? "زاد تأكد عندنا حيث الدخل الحالي ما كيخليش مساحة كبيرة للأخطاء."
          : "هاد الظرف كيبقى أساسي فالبداية باش تمتص أي مفاجأة.",
      source: "baseline",
      kind: "buffer",
      custom_amount: guidanceSnapshot ? guidanceSnapshot.planned_reserve : null,
    }),
    reasons
  );

  addProposalCandidate(
    candidates,
    withSmartRollover({
      name: "المرونة",
      group_key: "lifestyle",
      tier:
        !lifestyleFundableFromPlan
          ? "optional"
          : guidanceKeepsFlex
          ? objectivePolicy.mode === "debt" || salaryTight
            ? "recommended"
            : "core"
          : "optional",
      default_included: true,
      reason: !lifestyleFundableFromPlan
        ? "المعيشة كتبقى حاضرة فالبنية، ولكن التمويل ديالها مؤقتاً 0 حتى يتحسن الهامش."
        : guidanceKeepsFlex
        ? "كيجمع هامش المصاريف اليومية القابلة للتعديل بحال الخرجات والمطاعم والرفاهية الخفيفة."
        : "خليّناه اختياري حيث التوجيه اللي قبل اختار ما يفتحش مرونة مستقلة دابا.",
      objective_bias_effect:
        !lifestyleFundableFromPlan
          ? "الوضع الحالي مضغوط، لذلك الغلاف بقى حاضر ولكن بلا تمويل باش ما نخلقوش عجز جديد."
        : !guidanceKeepsFlex
          ? "ما تفعّلش تلقائياً حيث الاتجاه الحالي عطى الأولوية لبنود أخرى."
          : guidancePrioritizesGoals
          ? "خليّناه ظاهر ولكن بحجم محسوب باش الأهداف تبقى هي السابقة."
          : "هاد الظرف كيخلي المصاريف المتغيرة تبقى واضحة وما تخلطش مع الضروري.",
      source: "baseline",
      kind: "spend",
      custom_amount: lifestyleFundableFromPlan ? (guidanceSnapshot ? guidanceSnapshot.planned_flex : null) : 0,
    }),
    reasons
  );

  addProposalCandidate(
    candidates,
    withSmartRollover({
      name: "Nourriture",
      group_key: "essentials",
      tier: getProposalTierForDomain(objectivePolicy, "essentials", "core"),
      default_included: shouldIncludeKnownFixedProposal(
        "Nourriture",
        shouldDefaultIncludeProposal(
          objectivePolicy,
          getProposalTierForDomain(objectivePolicy, "essentials", "core")
        )
      ),
      reason: "Base simple pour garder les dépenses quotidiennes visibles.",
      objective_bias_effect: "خلّيناه ظاهر باش يبقى المصروف اليومي واضح من الأول.",
      source: "baseline",
      kind: "spend",
    }),
    reasons
  );

  addProposalCandidate(
    candidates,
    withSmartRollover({
      name: "Factures",
      group_key: "bills",
      tier: getProposalTierForDomain(objectivePolicy, "bills", "core"),
      default_included: shouldIncludeKnownFixedProposal(
        "Factures",
        shouldDefaultIncludeProposal(
          objectivePolicy,
          getProposalTierForDomain(objectivePolicy, "bills", "core")
        )
      ),
      reason: salaryTight
        ? "كيجمع المصاريف الشهرية الثابتة فبلاصة واضحة حيث الثابت واخد حصة مهمة من الدخل."
        : "كيجمع المصاريف الشهرية الثابتة فبلاصة واضحة.",
      objective_bias_effect:
        objectivePolicy.mode === "organize"
          ? "تعمدنا نخليه بسيط وواضح باش التنظيم يبقى ساهل."
          : "خلاه فالمقدمة باش المصاريف الثابتة يبانو بسرعة.",
      source: "baseline",
      kind: "spend",
    }),
    reasons
  );

  if (objectivePolicy.mode !== "debt") {
    const healthTier =
      objectivePolicy.mode === "organize" || salaryTight ? "recommended" : "core";
    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: "Santé",
        group_key: "essentials",
        tier: healthTier,
        default_included: shouldIncludeKnownFixedProposal(
          "Santé",
          shouldDefaultIncludeProposal(objectivePolicy, healthTier)
        ),
        reason: "كيبقى مفيد إلا بغيت تفصل المصاريف الصحية بوحدها.",
        objective_bias_effect: "باقي ثانوي ولكن مهم باش الميزانية تبان أوضح.",
        source: "suggested",
        kind: "spend",
      }),
      reasons
    );
  }

  housingEntries.forEach((housingEntry) => {
    const housingTier = getProposalTierForDomain(
      objectivePolicy,
      housingEntry.group_key,
      housingEntry.fallback_tier ?? "core"
    );
    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: housingEntry.name,
        group_key: housingEntry.group_key,
        tier: housingTier,
        default_included: shouldIncludeKnownFixedProposal(
          housingEntry.name,
          shouldDefaultIncludeProposal(objectivePolicy, housingTier)
        ),
        reason: salaryTight
          ? `${housingEntry.reason} وزاد بان ضروري أكثر حيث ضغط السكن حاضر مع الدخل الحالي.`
          : housingEntry.reason,
        objective_bias_effect: housingEntry.objective_bias_effect,
        source: housingEntry.source,
        kind: housingEntry.kind,
      }),
      reasons
    );
  });

  transportEntries.forEach((transportEntry) => {
    const transportTier = transportEntry.fallback_tier ?? getProposalTierForDomain(objectivePolicy, "transport", "core");
    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: transportEntry.name,
        group_key: "transport",
        tier: transportTier,
        default_included: shouldIncludeKnownFixedProposal(
          transportEntry.name,
          shouldDefaultIncludeProposal(objectivePolicy, transportTier)
        ),
        reason: salaryTight
          ? `${transportEntry.reason} وزاد ولا مهم أكثر حيث التنقل باين فالمصاريف الشهرية الحالية.`
          : transportEntry.reason,
        objective_bias_effect: transportEntry.objective_bias_effect,
        source: transportEntry.source,
        kind: transportEntry.kind,
      }),
      reasons
    );
  });

  fixedItemEntries.forEach((fixedEntry) => {
    const fixedTier =
      fixedEntry.fallback_tier ?? getProposalTierForDomain(objectivePolicy, fixedEntry.group_key, "recommended");
    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: fixedEntry.name,
        group_key: fixedEntry.group_key,
        tier: fixedTier,
        default_included: shouldIncludeKnownFixedProposal(
          fixedEntry.name,
          shouldDefaultIncludeProposal(objectivePolicy, fixedTier)
        ),
        reason: fixedEntry.reason,
        objective_bias_effect:
          salaryTight && fixedEntry.group_key !== "family"
            ? `${fixedEntry.objective_bias_effect} وخلاّناه محافظ حيث الدخل الحالي خاصو يبان عليه الضروري أولاً.`
            : fixedEntry.objective_bias_effect,
        source: fixedEntry.source,
        kind: fixedEntry.kind,
      }),
      reasons
    );
  });

  if (objectivePolicy.mode === "save" || objectivePolicy.mode === "balanced") {
    const savingTier = guidancePrioritizesGoals
      ? "optional"
      : objectivePolicy.mode === "save"
      ? salaryTight
        ? "recommended"
        : "core"
      : salaryComfortable
      ? "recommended"
      : "optional";
    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: "Épargne / توفير",
        group_key: "saving",
        tier: savingTier,
        default_included:
          guidancePrioritizesGoals ? false : shouldDefaultIncludeProposal(objectivePolicy, savingTier),
        reason: guidancePrioritizesGoals
          ? "بقيناه اختياري لأن الاتجاه المختار كيعطي الأولوية للأهداف المباشرة أكثر من الادخار العام."
          : salaryTight
          ? "بقيناه حاضر ولكن بشكل محافظ لأن الدخل الحالي خاصو يغطّي الأولويات قبل كلشي."
          : "تزاد هنا حيث الهدف ديالك كيميل للتجميع والتوفير.",
        objective_bias_effect:
          guidancePrioritizesGoals
            ? "ما طلعش من الأول باش ما يكررش الدور ديال الأهداف فهاد المرحلة."
            : objectivePolicy.mode === "save"
            ? "دفعناه للفوق وخليّناه متفعل من الأول."
            : "بقيناه حاضر باش الاقتراح يبقى متوازن.",
        source: "baseline",
        kind: "saving",
      }),
      reasons
    );
  }

  addProposalCandidate(
    candidates,
    withSmartRollover({
      name: "الباقي الحر",
      group_key: "saving",
      tier: guidanceSnapshot && guidanceSnapshot.planned_free > 0 ? "recommended" : "optional",
      default_included: Boolean(guidanceSnapshot && guidanceSnapshot.planned_free > 0),
      reason: "كيجمع المبلغ اللي باقي بلا تخصيص نهائي حتى تبقى عندك مساحة قرار من بعد.",
      objective_bias_effect:
        guidanceSnapshot && guidanceSnapshot.planned_free > 0
          ? "طلعناه لأن التوجيه خلا جزء حر خاصو يبقى ظاهر وما يضيعش بين الأظرفة."
          : "خليّناه اختياري إلا بغيتي تخلي جزء مرن خارج التخصيص المباشر.",
      source: "suggested",
      kind: "saving",
    }),
    reasons
  );

  addProposalCandidate(
    candidates,
    withSmartRollover({
      name: "التوازن",
      group_key: "buffer",
      tier:
        objectivePolicy.mode === "balanced" || guidancePrioritizesSafety
          ? "recommended"
          : "optional",
      default_included: objectivePolicy.mode === "balanced" || guidancePrioritizesSafety,
      reason: "كيشد الفروقات الصغيرة بين الشهور باش الخطة تبقى مستقرة وما يطيحش الضغط على ظرف واحد.",
      objective_bias_effect:
        guidancePrioritizesSafety
          ? "بقيناه حاضر حيث الاستقرار محتاج مساحة توازن بين الأشهر."
          : "مفيد إلا بغيتي تبقي الخطة مستقرة حتى مع تغييرات صغيرة فالمصاريف.",
      source: "suggested",
      kind: "buffer",
    }),
    reasons
  );

  debtEntries.forEach((debtEntry) => {
    const debtTier = guidancePrioritizesDebt
      ? "core"
      : getProposalTierForDomain(objectivePolicy, "debts", objectivePolicy.mode === "debt" ? "core" : "recommended");
    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: debtEntry.name,
        group_key: "debts",
        tier: debtTier,
        default_included:
          guidanceSnapshot && guidanceSnapshot.planned_debt > 0
            ? true
            : shouldIncludeKnownFixedProposal(
                debtEntry.name,
                shouldDefaultIncludeProposal(objectivePolicy, debtTier)
              ),
        reason: debtEntry.reason,
        objective_bias_effect:
          guidancePrioritizesDebt
            ? `${debtEntry.objective_bias_effect} وطلعناه للفوق لأن التوجيه اختار يدفع للدين بمبلغ واضح دابا.`
            : objectivePolicy.mode === "debt"
            ? `${debtEntry.objective_bias_effect} وطلعناه للفوق حيث الهدف ديالك هو تسديد الديون.`
            : debtEntry.objective_bias_effect,
        source: debtEntry.source,
        kind: debtEntry.kind,
      }),
      reasons
    );
  });

  goalEntries.forEach((goalEntry) => {
    const goalTier = guidancePrioritizesGoals
      ? "core"
      : goalEntry.fallback_tier ?? getProposalTierForDomain(objectivePolicy, "goals", "recommended");
    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: goalEntry.name,
        group_key: "goals",
        tier: goalTier,
        default_included:
          guidanceSnapshot && guidanceSnapshot.planned_goals > 0
            ? true
            : shouldDefaultIncludeProposal(objectivePolicy, goalTier),
        reason: goalEntry.reason,
        objective_bias_effect: guidancePrioritizesGoals
          ? `${goalEntry.objective_bias_effect} وطلعناه من الأول لأن التوجيه اختار تمويل الأهداف بشكل مباشر.`
          : goalEntry.objective_bias_effect,
        source: goalEntry.source,
        kind: goalEntry.kind,
      }),
      reasons
    );
  });

  familyEntries.forEach((familyEntry) => {
    const familyTier =
      familyEntry.fallback_tier === "optional" && salaryTight
        ? "optional"
        : familyEntry.fallback_tier === "recommended" && objectivePolicy.mode === "save" && !salaryTight
        ? "recommended"
        : objectivePolicy.mode === "debt"
        ? "recommended"
        : familyEntry.fallback_tier ?? "core";

    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: familyEntry.name,
        group_key: "family",
        tier: familyTier,
        default_included: shouldIncludeKnownFixedProposal(
          familyEntry.name,
          shouldDefaultIncludeProposal(objectivePolicy, familyTier)
        ),
        reason: familyEntry.reason,
        objective_bias_effect:
          familyEntry.name.includes("École") || familyEntry.name.includes("مدرسة")
            ? objectivePolicy.mode === "save"
              ? `${familyEntry.objective_bias_effect} وخليّناه قريب للتحديد حيث بعض مصاريف المدرسة كتتجمع مع الوقت.`
              : salaryTight
              ? `${familyEntry.objective_bias_effect} وبقيناه ثانوي فهاد المرحلة باش ما يتشعبش عليك التنظيم.`
              : familyEntry.objective_bias_effect
            : familyEntry.objective_bias_effect,
        source: familyEntry.source,
        kind: familyEntry.kind,
      }),
      reasons
    );
  });

  lifestyleEntries.forEach((entry) => {
    const tier: EnvelopeProposalTier =
      !guidanceKeepsFlex
        ? "optional"
        : salaryTight
        ? "optional"
        : lifestyleChoice === "high" && entry.name === "Loisirs"
        ? "core"
        : lifestyleChoice === "high"
        ? "recommended"
        : salaryComfortable && objectivePolicy.mode === "balanced" && entry.name === "Loisirs"
        ? "recommended"
        : getProposalTierForDomain(objectivePolicy, "lifestyle", entry.fallback_tier ?? "optional");
    addProposalCandidate(
      candidates,
      withSmartRollover({
        name: entry.name,
        group_key: "lifestyle",
        tier,
        default_included: true,
        reason: guidanceKeepsFlex
          ? entry.reason
          : "بقيناه غير اختياري لأن التوجيه اللي قبل اختار ما يفتحش ظرف مرونة مستقل دابا.",
        objective_bias_effect:
          !guidanceKeepsFlex
            ? "ما تفعلش تلقائياً باش ما يبقاش كاين تكرار مع المبلغ الحر والباقي اللي ما تخصّصش."
            : salaryTight
            ? `${entry.objective_bias_effect} وهبطناه دابا لأن الدخل الحالي خاصو يبان عليه الضروري قبل الكماليات.`
            : objectivePolicy.mode === "balanced"
            ? `${entry.objective_bias_effect} وبقيناه حاضر ولكن بلا ما يطغى على الضروريات.`
            : `${entry.objective_bias_effect} وهبطناه لثانوي باش ما يزاحمش الهدف الرئيسي.`,
        source: entry.source,
        kind: entry.kind,
      }),
      reasons
    );
  });

  return [...candidates].sort((a, b) => {
    const domainDelta = proposalSortValue(a.group_key) - proposalSortValue(b.group_key);
    if (domainDelta !== 0) return domainDelta;
    const tierDelta = getProposalTierRank(a.tier) - getProposalTierRank(b.tier);
    if (tierDelta !== 0) return tierDelta;
    return a.name.localeCompare(b.name, "fr");
  });
}

function getProposalDomainLabelForUi(groupKey: EnvelopeProposalDomain): string {
  switch (groupKey) {
    case "buffer":
      return "الاحتياط";
    case "saving":
      return "التوفير";
    case "housing":
      return "السكن";
    case "transport":
      return "النقل";
    case "bills":
      return "الفواتير";
    case "debts":
      return "الديون";
    case "goals":
      return "الأهداف";
    case "lifestyle":
      return "المعيشة";
    case "family":
      return "العائلة";
    case "essentials":
      return "الضروريات";
    case "pro":
      return "الخدمة";
    default:
      return "أظرفة مقترحة";
  }
}

function getProposalReasonForUi(reason: string): string {
  const normalized = normalizeTextInput(reason);
  if (!normalized) return "هاد الظرف تقترح حسب الأجوبة ديالك.";
  if (normalized === "Toujours proposé comme buffer de sécurité pour absorber les écarts.") {
    return "كنقترحوه ديما باش يبقى عندك احتياط صغير لأي مفاجأة ولا فرق فالمصاريف.";
  }
  if (normalized === "Base simple pour garder les dépenses quotidiennes visibles.") {
    return "خلّيناه بسيط باش المصاريف اليومية يبقاو ظاهرين قدّامك.";
  }
  return normalized
    .replaceAll("charges", "مصاريف")
    .replaceAll("lifestyle", "المعيشة")
    .replaceAll("preview", "المعاينة");
}

function localizeProposalEnvelopeNameForUi(name: string): string {
  const normalized = normalizeTextInput(name);
  if (normalized === "التسوق" || normalized === "shopping" || normalized === "الشوبينغ") {
    return "الشوبينغ";
  }
  const slug = slugify(normalized);
  if (!slug) return name;
  if (slug === "nourriture") return "الماكلة";
  if (slug === "sante" || slug === "sant") return "الصحة";
  if (slug === "loyer") return "الكراء";
  if (slug === "transport") return "التنقل";
  if (slug === "imprevus" || slug === "urgences" || slug === "emergency" || slug === "emergencies") {
    return "الطوارئ";
  }
  if (slug === "factures") return "لفواتير";
  if (slug === "aide_famille" || slug === "famille_aide") return "مساعدة العائلة";
  if (slug === "objectif-principal") return "الهدف الرئيسي";
  if (slug === "loisirs") return "الترفيه";
  if (slug === "maison") return "الدار";
  if (slug === "entretien_maison") return "صيانة الدار";
  if (slug === "charges") return "مصاريف السكن";
  if (slug === "internet_telephone") return "النت/التليفون";
  if (slug === "carburant") return "المازوط";
  if (slug === "assurance_auto") return "تأمين الطوموبيل";
  if (slug === "controle_technique") return "الفحص التقني";
  if (slug === "credit_auto") return "قرض الطوموبيل";
  if (slug === "entretien_auto") return "صيانة الطوموبيل";
  if (slug === "taxe_auto") return "ضريبة الطوموبيل";
  if (slug === "parking") return "الباركينغ";
  if (slug === "cash") return "لكاش";
  if (slug === "epargne" || slug === "epargnes" || slug === "savings") return "الادخار";
  if (normalized.startsWith("Dettes — ")) return `الديون — ${normalized.slice("Dettes — ".length)}`;
  if (normalized.startsWith("Dettes - ")) return `الديون — ${normalized.slice("Dettes - ".length)}`;
  if (normalized.startsWith("Objectif ")) return normalized.replace(/^Objectif\b/, "الهدف");
  return name;
}

