function getGoalSemanticButtonClass(
  group: GoalChoiceGroup,
  value: string,
  selected: boolean,
  variant: "pill" | "card" = "pill"
): string {
  const palette = getGoalChoicePalette(group, value);
    const base =
      variant === "card"
        ? "rounded-[18px] border px-3 py-3 text-right transition"
        : "rounded-full border px-3 py-1.5 text-[12px] font-semibold transition";
  return `${base} ${selected ? palette.selected : palette.idle}`;
}

function getResolvedAdultsCount(answers: Answers): number {
  const household = getString(answers, "E0_household_type");
  if (household === "single") return 1;
  if (household === "couple") return 2;
  if (household === "family_kids") return 2;
  if (household === "extended_family") {
    const sharedCount = getString(answers, "E0sh_people_count");
    if (sharedCount === "2") return 2;
    if (sharedCount === "3") return 3;
    if (sharedCount === "4_plus") return 4;
  }
  return 1;
}

function getResolvedKidsCount(answers: Answers): number {
  const household = getString(answers, "E0_household_type");
  if (household !== "family_kids") return 0;
  return toNumber(getString(answers, "E2_kids_count"));
}

function parseCustomEnvelopeDraft(rawValue: string): string[] {
  return Array.from(
    new Map(
      rawValue
        .replace(/،/g, ",")
        .split(",")
        .map((item) => normalizeTextInput(item))
        .filter(Boolean)
        .map((item) => [item.toLowerCase(), item] as const)
    ).values()
  );
}

function deriveDebtEnvelopeNames(answers: Answers): string[] {
  if (getString(answers, "E5_has_debt") !== "yes") return [];
  const count = getDebtCount(answers);
  const names: string[] = [];
  for (let i = 1; i <= count; i += 1) {
    const name = getString(answers, `D2_debt_name_${i}`).trim();
    if (name) names.push(name);
  }
  return uniqueBySlug(names);
}

function getDebtProposalEntries(
  answers: Answers,
  _namingStyle: ObjectivePolicy["naming_style"]
): HousingProposalEntry[] {
  if (getString(answers, "E5_has_debt") !== "yes") return [];

  const debtNames = deriveDebtEnvelopeNames(answers);
  const granularity = getEnvelopeGranularity(answers);
  const simpleMode = granularity === "simple";
  const hasDebtStrategy = Boolean(getString(answers, "D2_preferred_strategy") || getString(answers, "D7_debt_strategy"));
  const hasExtraDebtPush = getString(answers, "D8_debt_extra_monthly") === "yes";

  if (debtNames.length === 0) {
    return [
      {
        name: "Dettes",
        group_key: "debts",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: "بان بلي عندك ديون، لذلك خليّنا ليها ظرف عام حتى تتوضح أكثر.",
        objective_bias_effect: "ما زدناش تفاصيل من عندنا حيث مازال الأسماء الحقيقية ما توضحاتش.",
      },
    ];
  }

  if (simpleMode && debtNames.length > 1) {
    return [
      {
        name: "Dettes",
        group_key: "debts",
        kind: "spend",
        source: "suggested",
        fallback_tier: "core",
        reason: "جمعنا الديون فظرف واحد باش يبقى التنظيم بسيط فهاد المرحلة.",
        objective_bias_effect:
          hasExtraDebtPush || hasDebtStrategy
            ? "التفاصيل بقاو موجودين فالجوابات، ولكن فالواجهة بقينا مختصرين باش ما تتشعبش عليك اللائحة."
            : "بقيناه مبسط حتى إلا كانت أكثر من دين واحد.",
      },
    ];
  }

  return debtNames.map((debtName) => ({
    name: `Dettes — ${debtName}`,
    group_key: "debts",
    kind: "spend",
    source: "suggested",
    fallback_tier: "core",
    reason:
      debtNames.length > 1
        ? "فصلنا هاد الدين بوحدو حيث عندك أكثر من دين وبغيتي preview أوضح."
        : "الاسم جا من الجوابات ديالك، لذلك خلّيناه ظاهر كما هو.",
    objective_bias_effect:
      hasExtraDebtPush || hasDebtStrategy
        ? "هكذا يولي سهل من بعد نبيّنو ليك شكون خاصو الأولوية فالتسديد."
        : "بقيناه بنفس الاسم باش الاقتراح يبقى مطابق للواقع.",
  }));
}

function getFamilyProposalEntries(
  answers: Answers,
  namingStyle: ObjectivePolicy["naming_style"]
): HousingProposalEntry[] {
  const supportsFamily = getString(answers, "E6_support_family") === "yes";
  const kidsCount = getResolvedKidsCount(answers);
  const hasSchoolNeed =
    getList(answers, "FX1_fixed_items").includes("school") || getString(answers, "E0f_school_costs") === "yes";
  const schoolCycleLabel = getSchoolPaymentCycleLabel(answers);
  const schoolCycleReason = getSchoolCycleReason(answers);
  const coupleSharedItems = getCoupleSharedItems(answers);
  const hasSharedKidsContext = coupleSharedItems.has("kids");

  if (!supportsFamily && kidsCount <= 0 && !hasSchoolNeed && !hasSharedKidsContext) return [];

  const granularity = getEnvelopeGranularity(answers);
  const simpleMode = granularity === "simple";
  const compactNaming = simpleMode || namingStyle === "generic";
  const entries: HousingProposalEntry[] = [];

  if (supportsFamily) {
    entries.push({
      name: compactNaming ? "Aide famille" : "Famille — Aide",
      group_key: "family",
      kind: "spend",
      source: "suggested",
      fallback_tier: "core",
      reason: "تزاد حيث جاوبتي بلي كتعون العائلة شهرياً.",
      objective_bias_effect:
        simpleMode
          ? "بقيناه واضح وبسيط باش يبان الالتزام العائلي بلا تفاصيل زايدة."
          : "وضحناه أكثر باش الدعم الشهري يبقى باين بوحدو.",
    });
  }

  if (kidsCount > 0) {
    entries.push({
      name: compactNaming ? "Enfants" : "Famille — Enfants",
      group_key: "family",
      kind: "spend",
      source: "suggested",
      fallback_tier: "core",
      reason: "كاينين أطفال فالجوابات، لذلك زدنا ظرف خاص بالمصاريف ديالهم.",
      objective_bias_effect:
        simpleMode
          ? "خلّيناه مختصر باش تبقى اللائحة مفهومة بسرعة."
          : "فصلناه باش يبان شنو خاص بالأطفال بوحدو.",
    });
  } else if (hasSharedKidsContext) {
    entries.push({
      name: compactNaming ? "Enfants" : "Famille — Enfants",
      group_key: "family",
      kind: "spend",
      source: "suggested",
      fallback_tier: "recommended",
      reason: "بينتي بلي جزء من المصاريف المشتركة كيمشي للأطفال، لذلك زدناه بوضوح فهاد المرحلة.",
      objective_bias_effect: "هاد الظرف كيعكس غير الجزء اللي دخلتيه نتا، بلا ما نقسمو المبلغ من جديد.",
    });
  }

  if (hasSchoolNeed) {
    entries.push({
      name: compactNaming ? "École/Crèche" : "Famille — École",
      group_key: "family",
      kind: "accumulating",
      source: "suggested",
      fallback_tier: simpleMode ? "recommended" : "optional",
      reason: schoolCycleReason
        ? `${schoolCycleReason}${schoolCycleLabel ? ` نوع الأداء: ${schoolCycleLabel}.` : ""}`
        : "مفيد إلا كانت المدرسة أو المصاريف المشابهة داخلة فالحساب.",
      objective_bias_effect:
        simpleMode
          ? "بقيناه ظاهر ولكن بلا تفصيل كبير باش ما تتشعبش اللائحة."
          : "خليّناه مستقل حيث مصاريف المدرسة كتحتاج توضيح أكثر.",
    });
  }

  return entries;
}

function getFixedItemProposalEntries(
  answers: Answers,
  namingStyle: ObjectivePolicy["naming_style"]
): HousingProposalEntry[] {
  const fixedItems = new Set(getList(answers, "FX1_fixed_items"));
  const fixedOtherRows = getFixedOtherRows(answers);
  const granularity = getEnvelopeGranularity(answers);
  const simpleMode = granularity === "simple";
  const detailedMode = granularity === "detailed";
  const transportMode = getString(answers, "E4_transport_mode");
  const primaryTransportName = getTransportProposalEntries(answers, namingStyle)[0]?.name;
  const coupleSharedItems = getCoupleSharedItems(answers);
  const extendedSharedFixedItems = getExtendedSharedFixedItems(answers);
  const schoolCycleReason = getSchoolCycleReason(answers);
  const entries: HousingProposalEntry[] = [];

  const hasSharedBillsContext =
    coupleSharedItems.has("bills") ||
    extendedSharedFixedItems.has("internet") ||
    extendedSharedFixedItems.has("utilities");
  const hasSharedTransportContext = coupleSharedItems.has("transport");
  const hasSharedHousingContext =
    coupleSharedItems.has("rent_or_loan") ||
    extendedSharedFixedItems.has("rent") ||
    extendedSharedFixedItems.has("cleaning_house");
  const hasSharedOtherContext = coupleSharedItems.has("other") || extendedSharedFixedItems.has("other");

  if (
    fixedItems.size === 0 &&
    !hasSharedBillsContext &&
    !hasSharedTransportContext &&
    !hasSharedHousingContext &&
    !hasSharedOtherContext
  ) {
    return [];
  }

  if (fixedItems.has("bills") || hasSharedBillsContext) {
    entries.push({
      name: "Factures",
      group_key: "bills",
      kind: "spend",
      source: "suggested",
      fallback_tier: "core",
      reason: hasSharedBillsContext
        ? "لفواتير بانت حتى فالمصاريف المشتركة الثابتة، لذلك خرجناها بوضوح من الأول."
        : "تأكدات لفواتير أكثر حيث جاوبتي بلي عندك مصاريف ثابتة من هاد النوع.",
      objective_bias_effect: hasSharedBillsContext
        ? "هاد الظرف كيعكس غير الجزء اللي دخلتيه نتا من هاد المصاريف، بلا ما نقسموه من جديد."
        : "بقات فالأولوية حيث هاد الثابت خاصو يبان بسرعة.",
    });
  }

  if (fixedItems.has("internet_phone") || extendedSharedFixedItems.has("internet")) {
    entries.push(
      simpleMode
        ? {
            name: "Factures",
            group_key: "bills",
            kind: "spend",
            source: "suggested",
            fallback_tier: "recommended",
            reason: extendedSharedFixedItems.has("internet")
              ? "الأنترنت داخل فالمصاريف المشتركة الثابتة، لذلك خلّيناه ظاهر داخل لفواتير."
              : "دخلنا النت والتليفون داخل لفواتير باش يبقى التنظيم بسيط.",
            objective_bias_effect: extendedSharedFixedItems.has("internet")
              ? "بقيناه مجمّع بلا ما نعاودو نقسمو المبلغ حيث المدخول ديالك راه أصلاً هو الجزء ديالك."
              : "بقيناه مجمّع مع الفواتير حيث اخترتي مستوى مبسط.",
          }
        : {
            name: "Internet/Téléphone",
            group_key: "bills",
            kind: "spend",
            source: "suggested",
            fallback_tier: "recommended",
            reason: extendedSharedFixedItems.has("internet")
              ? "الأنترنت بان فالمصاريف المشتركة الثابتة، لذلك خرجناه بوحدو باش يبقى واضح."
              : "النت والتليفون بانوا كالتزام ثابت، لذلك خرجناهم بوحدهم.",
            objective_bias_effect: extendedSharedFixedItems.has("internet")
              ? "هاد الظرف كيعكس غير الحصة اللي دخلتي نتا، وما تبدل حتى تقسيم فالمبلغ."
              : "تفصلو غير ملي بان بلي محتاج وضوح أكثر فالثوابت.",
          }
    );
  }

  if (fixedItems.has("insurance")) {
    if (transportMode === "car") {
      entries.push({
        name: "Assurance auto",
        group_key: "transport",
        kind: "accumulating",
        source: "suggested",
        fallback_tier: "recommended",
        reason: "التأمين ثابت ومهم، لذلك قوّينا حضوره فالجزء ديال التنقل.",
        objective_bias_effect: "ما زدناش تأمين عام حتى ما نكرروش نفس المصروف.",
      });
    } else {
      entries.push(
        simpleMode
          ? {
              name: "Factures",
              group_key: "bills",
              kind: "spend",
              source: "suggested",
              fallback_tier: "recommended",
              reason: "دخلنا التأمين داخل لفواتير باش يبقى كلشي بسيط.",
              objective_bias_effect: "بقيناه مجموع مع الثوابت حيث هاد المستوى ما محتاجش تفصيل كبير.",
            }
          : {
              name: "Assurance",
              group_key: "bills",
              kind: "accumulating",
              source: "suggested",
              fallback_tier: "recommended",
              reason: "التأمين بان فالمصاريف الثابتة، لذلك خرجناه بظرف واضح.",
              objective_bias_effect: "فصلناه باش ما يضيعش وسط باقي الفواتير.",
            }
      );
    }
  }

  if (fixedItems.has("fixed_transport") || hasSharedTransportContext) {
    if (detailedMode) {
      entries.push({
        name: "Transport fixe",
        group_key: "transport",
        kind: "spend",
        source: "suggested",
        fallback_tier: fixedItems.has("fixed_transport") ? "optional" : "recommended",
        reason: hasSharedTransportContext
          ? "التنقل بان ضمن المصاريف المشتركة، لذلك خرجناه بظرف واضح فالوضع المفصل."
          : "زدناه حيث التنقل الثابت بان كجزء واضح من المصاريف الشهرية.",
        objective_bias_effect: hasSharedTransportContext
          ? "هاد الظرف كيبين غير الجزء اللي كتخلص نتا فالتنقل، بلا إعادة تقسيم."
          : "ظهر غير فالوضع المفصل باش ما نكثروش الأظرفة فالمستويات الأخرى.",
      });
    } else if (primaryTransportName) {
      entries.push({
        name: primaryTransportName,
        group_key: "transport",
        kind: "spend",
        source: "suggested",
        fallback_tier: "recommended",
        reason: hasSharedTransportContext
          ? "التنقل بان كمصروف مشترك واضح، لذلك قوّينا حضورو فالاقتراح."
          : "قوّيناه أكثر حيث جاوبتي بلي التنقل عندك ثابت شهرياً.",
        objective_bias_effect: hasSharedTransportContext
          ? "بقيناه ظاهر حيث المبلغ اللي دخلتيه راه هو الجزء ديالك وما خاصوش تقسيم آخر."
          : "هاد الجواب كيزيد يثبت أن التنقل خاصو يبقى ظاهر فالأولوية.",
      });
    }
  }

  if (fixedItems.has("school")) {
    entries.push({
      name: simpleMode ? "École/Crèche" : "Famille — École",
      group_key: "family",
      kind: "accumulating",
      source: "suggested",
      fallback_tier: "recommended",
      reason: schoolCycleReason
        ? `المدرسة دخلات ضمن المصاريف الثابتة. ${schoolCycleReason}`
        : "المدرسة دخلات ضمن المصاريف الثابتة، لذلك رفعنا حضورها فالاقتراح.",
      objective_bias_effect: "بانت كالتزام واضح وما بقاتش غير احتمال ثانوي.",
    });
  }

  if (fixedItems.has("other") || hasSharedOtherContext || extendedSharedFixedItems.has("cleaning_house")) {
    if (fixedOtherRows.length > 0) {
      fixedOtherRows.forEach((row) => {
        entries.push({
          name: row.name,
          group_key: "bills",
          kind: "spend",
          source: "suggested",
          fallback_tier: hasSharedOtherContext || extendedSharedFixedItems.has("cleaning_house") ? "recommended" : "optional",
          reason:
            hasSharedOtherContext || extendedSharedFixedItems.has("cleaning_house")
              ? "هاد المصروف ثابت ومشترك، لذلك خرجناه بظرف بوحدو باش يبقى واضح."
              : "هاد المصروف ثابت، لذلك خرجناه بظرف بوحدو باش يبقى واضح.",
          objective_bias_effect:
            hasSharedOtherContext || extendedSharedFixedItems.has("cleaning_house")
              ? "المبلغ كيعكس غير الجزء اللي دخلتي نتا بلا إعادة تقسيم."
              : "تفصيل إضافي باش كل مصروف ثابت يبقى متتبع بوحدو.",
        });
      });
    } else {
      entries.push({
        name: "Autres fixes",
        group_key: "bills",
        kind: "spend",
        source: "suggested",
        fallback_tier: hasSharedOtherContext || extendedSharedFixedItems.has("cleaning_house") ? "recommended" : "optional",
        reason:
          extendedSharedFixedItems.has("cleaning_house")
            ? "مصاريف الدار المشتركة بحال المنظفات ولا اللوازم بانوا كمصروف ثابت، لذلك جمعناهم هنا بوضوح."
            : hasSharedOtherContext
            ? "كاين جزء آخر من المصاريف المشتركة الثابتة، لذلك جمعناه فظرف واضح حتى ما يضيعش."
            : "كاين مصروف ثابت آخر ما تسمّاش بالتفصيل، لذلك جمعناه هنا بوضوح.",
        objective_bias_effect:
          hasSharedOtherContext || extendedSharedFixedItems.has("cleaning_house")
            ? "هاد الظرف كيبقى كيعكس غير الجزء اللي كتخلص نتا، بلا أي إعادة تقسيم."
            : "خلّيناه ثانوي باش ما يبانش أعرض من اللازم.",
      });
    }
  }

  if (hasSharedHousingContext && !simpleMode) {
    entries.push({
      name: "Charges",
      group_key: "housing",
      kind: "spend",
      source: "suggested",
      fallback_tier: "recommended",
      reason: "كاينين مصاريف سكن مشتركة ثابتة، لذلك خرجنا ليها ظرف واضح فجزء السكن.",
      objective_bias_effect: "هاد الظرف كيعكس غير الجزء اللي دخلتيه نتا فالسكن، بلا إعادة تقسيم للمبلغ.",
    });
  }

  return entries;
}

function deriveSelectedDomains(answers: Answers): string[] {
  const fromFixed = getList(answers, "FX1_fixed_items").map((item) => {
    if (item === "internet_phone") return "bills";
    if (item === "loan") return "debt";
    if (item === "school") return "other";
    if (item === "insurance") return "bills";
    if (item === "fixed_transport") return "transport";
    return item;
  });
  const heuristics: string[] = [];
  const housing = getString(answers, "E3_housing_status");
  const transport = getString(answers, "E4_transport_mode");
  const hasDebt = getString(answers, "E5_has_debt") === "yes";
  const lifestyle = getString(answers, "E7_lifestyle");

  if (housing) heuristics.push("rent", "bills");
  if (transport) heuristics.push("transport");
  heuristics.push("food", "health", "savings");
  if (hasDebt) heuristics.push("debt");
  if (lifestyle === "medium" || lifestyle === "high") heuristics.push("other");

  const merged = [...heuristics, ...fromFixed];
  return Array.from(new Set(merged));
}

function uniqueBySlug(values: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  values.forEach((value) => {
    const slug = slugify(value);
    if (!slug || seen.has(slug)) return;
    seen.add(slug);
    result.push(value.trim());
  });
  return result;
}

function getRelevantSuggestionGroupKeys(answers: Answers): string[] {
  const keys = ["essentials", "savings"];
  const housing = getString(answers, "E3_housing_status");
  const transport = getString(answers, "E4_transport_mode");
  const hasDebt = getString(answers, "E5_has_debt") === "yes";
  const fixedItems = new Set(getList(answers, "FX1_fixed_items"));
  const coupleSharedItems = getCoupleSharedItems(answers);
  const extendedSharedFixedItems = getExtendedSharedFixedItems(answers);
  const supportFamily = getString(answers, "E6_support_family") === "yes";
  const lifestyle = getString(answers, "E7_lifestyle");
  const hasGoal = getGoalBuilderEntries(answers).length > 0;
  const kids = getResolvedKidsCount(answers);
  const household = getString(answers, "E0_household_type");
  const incomeType = getString(answers, "Q0_income_type");
  const granularity = getEnvelopeGranularity(answers);

  if (housing) keys.push("housing");
  if (transport) keys.push("transport");
  if (coupleSharedItems.has("rent_or_loan") || extendedSharedFixedItems.has("rent") || extendedSharedFixedItems.has("cleaning_house")) {
    keys.push("housing");
  }
  if (["bills", "internet_phone", "insurance", "other"].some((item) => fixedItems.has(item))) {
    keys.push("bills");
  }
  if (coupleSharedItems.has("bills") || extendedSharedFixedItems.has("internet") || extendedSharedFixedItems.has("utilities") || extendedSharedFixedItems.has("other")) {
    keys.push("bills");
  }
  if (coupleSharedItems.has("transport")) keys.push("transport");
  if (kids > 0 || supportFamily || household === "family_kids") {
    keys.push("family");
  }
  if (coupleSharedItems.has("kids")) keys.push("family");
  if (hasGoal) keys.push("goals");
  if (hasDebt) keys.push("debt");
  if (lifestyle === "medium" || lifestyle === "high") keys.push("lifestyle");
  if (incomeType === "hirafi" || incomeType === "freelancer" || incomeType === "mixed" || granularity === "detailed") {
    keys.push("pro");
  }

  return Array.from(new Set(keys));
}

function filterGroupNamesByContext(groupKey: string, names: string[], answers: Answers): string[] {
  const granularity = getEnvelopeGranularity(answers);
  const hasSpecificBillsContext =
    Boolean(getString(answers, "E3_housing_status")) ||
    ["bills", "internet_phone", "insurance", "other"].some((item) =>
      getList(answers, "FX1_fixed_items").includes(item)
    );

  if (groupKey === "housing") {
    const allowed = new Set(getHousingProposalEntries(answers, "explicit").map((entry) => entry.name));
    return names.filter((name) => allowed.has(name));
  }

  if (groupKey === "transport") {
    const allowed = new Set(getTransportProposalEntries(answers, "explicit").map((entry) => entry.name));
    getFixedItemProposalEntries(answers, "explicit")
      .filter((entry) => entry.group_key === "transport")
      .forEach((entry) => allowed.add(entry.name));
    return names.filter((name) => allowed.has(name));
  }

  if (groupKey === "family") {
    const derived = [
      ...getFamilyProposalEntries(answers, "explicit").map((entry) => entry.name),
      ...getFixedItemProposalEntries(answers, "explicit")
        .filter((entry) => entry.group_key === "family")
        .map((entry) => entry.name),
    ];
    if (derived.length > 0) return derived;
  }

  if (groupKey === "goals") {
    const derived = getGoalProposalEntries(answers, getObjectivePolicy(answers), null).map((entry) => entry.name);
    if (derived.length > 0) return uniqueBySlug(derived);
  }

  if (groupKey === "debt") {
    const derived = getDebtProposalEntries(answers, "explicit").map((entry) => entry.name);
    if (derived.length > 0) return derived;
  }

  if (groupKey === "lifestyle") {
    const derived = getLifestyleProposalEntries(answers, getObjectivePolicy(answers)).map((entry) => entry.name);
    if (derived.length > 0) return derived;
  }

  if (groupKey === "bills") {
    const derived = getFixedItemProposalEntries(answers, "explicit")
      .filter((entry) => entry.group_key === "bills")
      .map((entry) => entry.name);
    if (derived.length > 0) return uniqueBySlug(derived);
  }

  if (groupKey === "savings" && granularity === "simple") {
    return names.filter((name) => ["Épargne", "Urgences"].includes(name));
  }

  if (groupKey === "essentials" && granularity === "simple") {
    return names.filter((name) =>
      ["Courses", "Santé", "Divers", ...(!hasSpecificBillsContext ? ["Factures"] : [])].includes(name)
    );
  }

  if (groupKey === "essentials" && hasSpecificBillsContext) {
    return names.filter((name) => name !== "Factures");
  }

  if (groupKey === "pro" && granularity === "simple") {
    return names.filter((name) => ["Pro", "Matériel"].includes(name));
  }

  return names;
}

function getEnvelopeLabelForUi(name: string): string {
  if (name.startsWith("Objectif — ")) {
    return `الهدف — ${name.replace("Objectif — ", "").trim()}`;
  }
  if (name.startsWith("Dettes — ")) {
    return `الديون — ${name.replace("Dettes — ", "").trim()}`;
  }
  return ENVELOPE_LABEL_DARIJA[name] ?? name;
}

function getEnvelopeSetupShownAmount(params: {
  groupKey: EnvelopeProposalDomain;
  groupItemsCount: number;
  guidanceAmount: number | null;
  item: EnvelopeProposalResolved;
  answers: Answers;
}): number | null {
  const { groupKey, groupItemsCount, guidanceAmount, item, answers } = params;
  if (groupKey === "debts" && typeof guidanceAmount === "number" && guidanceAmount > 0) {
    const divisor = groupItemsCount > 0 ? groupItemsCount : 1;
    return guidanceAmount / divisor;
  }
  if (groupKey === "goals" && typeof guidanceAmount === "number" && guidanceAmount > 0) {
    const divisor = groupItemsCount > 0 ? groupItemsCount : 1;
    return guidanceAmount / divisor;
  }
  return item.custom_amount ?? getKnownProposalAmount(item.name, answers);
}

function getGuidanceAmountCopyForGroup(groupKey: EnvelopeProposalDomain, amount: number, label: string | null): string {
  if (groupKey === "buffer") return `غلاف الأمان: ${formatMad(amount)}`;
  if (groupKey === "lifestyle") return `غلاف المرونة: ${formatMad(amount)}`;
  if (groupKey === "saving" && label === "الباقي الحر") return `الباقي اللي مازال حر: ${formatMad(amount)}`;
  if (groupKey === "debts") return `التمويل الشهري الموجّه للديون: ${formatMad(amount)}`;
  if (groupKey === "goals") return `التمويل الشهري الموجّه للأهداف: ${formatMad(amount)}`;
  return `المبلغ اللي غادي نخدمو به هنا: ${formatMad(amount)}`;
}

function getKnownAmountCopyForGroup(groupKey: EnvelopeProposalDomain, amount: number): string {
  if (groupKey === "debts") return `القسط اللي باين دابا: ${formatMad(amount)}`;
  if (groupKey === "housing" || groupKey === "transport" || groupKey === "bills") {
    return `المصاريف اللي باينين دابا: ${formatMad(amount)}`;
  }
  if (groupKey === "family") return `اللي باين من الأجوبة: ${formatMad(amount)}`;
  return `اللي باين دابا: ${formatMad(amount)}`;
}

function getGoalRealityHintForUi(answers: Answers): string | null {
  const goals = getGoalBuilderEntries(answers);
  if (goals.length === 0) return null;
  const sanity = computeSanity(answers);
  const realisticMonthlyCap = getRealisticGoalMonthlyCapFromSanity(sanity);
  if (!realisticMonthlyCap || realisticMonthlyCap <= 0) return null;
  if (goals.length === 1) {
    const reality = buildGoalRealityCheckForEntry(goals[0], answers);
    if (reality.status === "realistic" || reality.status === "unknown") {
      return `الواقعي دابا: حتى ${formatMad(realisticMonthlyCap)} فالشهر.`;
    }
  }
  return goals.length > 1
    ? `الواقعي دابا للأهداف كاملين أقرب لـ ${formatMad(realisticMonthlyCap)} فالشهر.`
    : `الواقعي دابا أقرب لـ ${formatMad(realisticMonthlyCap)} فالشهر.`;
}

function getKnownProposalAmount(name: string, answers: Answers): number | null {
  const normalized = normalizeProposalName(name);
  if (!normalized) return null;
  const fixedOtherRows = getFixedOtherRows(answers);

  if (normalized === "Loyer") return toNumber(getString(answers, "RNT0_rent_amount")) || null;
  if (normalized === "Crédit logement") return toNumber(getString(answers, "HSN1_loan_monthly_amount")) || null;
  if (normalized === "Contribution famille") return toNumber(getString(answers, "HSN5a_with_family_amount")) || null;
  if (normalized === "Aide famille" || normalized === "Famille — Aide") {
    const monthly = getFamilySupportMonthlyAmount(answers);
    return monthly > 0 ? monthly : null;
  }
  if (normalized === "Entretien maison") return toNumber(getString(answers, "HSN4a_maintenance_saving_amount")) || null;
  if (
    normalized === "Factures" ||
    normalized === "Charges" ||
    normalized === "الفواتير الثابتة"
  ) {
    return toNumber(getString(answers, "FX2_amount_bills")) || null;
  }
  if (normalized === "Internet/Téléphone") return toNumber(getString(answers, "FX2_amount_internet_phone")) || null;
  if (normalized === "Assurance") return toNumber(getString(answers, "FX2_amount_insurance")) || null;
  if (normalized === "Transport fixe") return toNumber(getString(answers, "FX2_amount_fixed_transport")) || null;
  if (normalized === "École/Crèche" || normalized === "Famille — École") {
    return toNumber(getString(answers, "FX2_amount_school")) || null;
  }
  if (normalized === "Autres fixes") {
    const fixedOtherMonthly = fixedOtherRows.reduce(
      (sum, row) => sum + toMonthlyAmountFromFixedOtherCadence(row.amount, row.cadence, answers),
      0
    );
    return fixedOtherMonthly > 0 ? fixedOtherMonthly : null;
  }
  const matchedOtherTotal = fixedOtherRows.reduce((sum, row) => {
    if (normalizeProposalName(row.name) !== normalized) return sum;
    return sum + toMonthlyAmountFromFixedOtherCadence(row.amount, row.cadence, answers);
  }, 0);
  if (matchedOtherTotal > 0) return matchedOtherTotal;
  if (normalized === "Transport public") {
    const publicTransport =
      toNumber(getString(answers, "TRP1_public_monthly_amount")) +
      toNumber(getString(answers, "TRX_P_public_monthly_amount"));
    const publicTaxi = 0;
    const total = publicTransport + publicTaxi;
    return total > 0 ? total : null;
  }
  if (normalized === "Taxi / VTC") {
    const total =
      toNumber(getString(answers, "TRP1_taxi_monthly_amount")) +
      toNumber(getString(answers, "TRX_P_taxi_monthly_amount"));
    return total > 0 ? total : null;
  }
  if (normalized === "Transport") {
    const mixedTotal = shouldUseMixedTransportTotal(answers) ? toNumber(getString(answers, "TRX2_total_monthly_amount")) : 0;
    if (mixedTotal > 0) return mixedTotal;
    const publicTransport = toNumber(getString(answers, "TRP1_public_monthly_amount"));
    const publicTaxi = toNumber(getString(answers, "TRP1_taxi_monthly_amount"));
    const carTotal = getCarTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + getCarTransportMonthlyTotalForPrefix(answers, prefix),
      0
    );
    const bikeTotal = getBikeTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + getBikeTransportMonthlyTotalForPrefix(answers, prefix),
      0
    );
    const total = publicTransport + publicTaxi + carTotal + bikeTotal;
    return total > 0 ? total : null;
  }
  if (normalized === "Carburant") {
    const total = getCarTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + toNumber(getString(answers, `${prefix}car_fuel_amount`)),
      0
    );
    return total > 0 ? total : null;
  }
  if (normalized === "Assurance auto") {
    const monthly = getCarTransportPrefixes(answers).reduce((sum, prefix) => {
      const amount = toNumber(getString(answers, `${prefix}car_insurance_amount`));
      return sum + amount / insuranceCycleMonths(getString(answers, `${prefix}car_insurance_cycle`));
    }, 0);
    return monthly > 0 ? Number(monthly.toFixed(2)) : null;
  }
  if (normalized === "Entretien auto") {
    const total = getCarTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + getCarMaintenanceMonthlyAmount(answers, prefix),
      0
    );
    return total > 0 ? total : null;
  }
  if (normalized === "Parking") {
    const total = getCarTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + toNumber(getString(answers, `${prefix}car_parking_amount`)),
      0
    );
    return total > 0 ? total : null;
  }
  if (normalized === "Crédit auto") {
    const total = getCarTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + toNumber(getString(answers, `${prefix}car_loan_amount`)),
      0
    );
    return total > 0 ? total : null;
  }
  if (normalized === "Contrôle technique") {
    const total = getCarTransportPrefixes(answers).reduce(
      (sum, prefix) =>
        sum +
        toNumber(getString(answers, `${prefix}car_inspection_amount`)) /
          technicalInspectionCycleMonths(getString(answers, `${prefix}car_inspection_cycle`)),
      0
    );
    return total > 0 ? Number(total.toFixed(2)) : null;
  }
  if (normalized === "Taxe auto") {
    const total = getCarTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + toNumber(getString(answers, `${prefix}car_tax_annual_amount`)) / 12,
      0
    );
    return total > 0 ? Number(total.toFixed(2)) : null;
  }
  if (normalized === "Carburant 2 roues") {
    const total = getBikeTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + toNumber(getString(answers, `${prefix}bike_fuel_amount`)),
      0
    );
    return total > 0 ? total : null;
  }
  if (normalized === "Assurance 2 roues") {
    const total = getBikeTransportPrefixes(answers).reduce(
      (sum, prefix) =>
        sum +
        toNumber(getString(answers, `${prefix}bike_insurance_amount`)) /
          insuranceCycleMonths(getString(answers, `${prefix}bike_insurance_cycle`)),
      0
    );
    return total > 0 ? Number(total.toFixed(2)) : null;
  }
  if (normalized === "Entretien 2 roues") {
    const total = getBikeTransportPrefixes(answers).reduce(
      (sum, prefix) => sum + toNumber(getString(answers, `${prefix}bike_maintenance_amount`)),
      0
    );
    return total > 0 ? total : null;
  }

  if (normalized.startsWith("Dettes — ")) {
    const targetName = normalizeTextInput(normalized.replace("Dettes — ", ""));
    const count = getDebtCount(answers);
    for (let i = 1; i <= count; i += 1) {
      const debtName = normalizeTextInput(getString(answers, `D2_debt_name_${i}`));
      if (debtName && debtName === targetName) {
        return getDebtPaymentSnapshot(answers, i).monthly_equivalent || null;
      }
    }
  }

  if (normalized === "Objectif principal" || normalized === "Objectif" || normalized.startsWith("Objectif")) {
    const goalEntries = getGoalBuilderEntries(answers);
    for (const [index, goalEntry] of goalEntries.entries()) {
      const previewName = normalizeProposalName(
        getGoalPreviewName(goalEntry.name, answers, getObjectivePolicy(answers).naming_style, index + 1, goalEntries.length)
      );
      if (previewName && previewName === normalized) {
        return goalEntry.target_amount || null;
      }
    }
    return goalEntries[0]?.target_amount || null;
  }

  return null;
}

function isCommitmentLockDomain(groupKey: EnvelopeProposalDomain): boolean {
  return groupKey === "housing" || groupKey === "transport" || groupKey === "bills" || groupKey === "family" || groupKey === "debts";
}

function isProposalFixedCommitmentLocked(
  item: EnvelopeProposalResolved,
  answers: Answers
): boolean {
  if (!isCommitmentLockDomain(item.group_key)) return false;
  const knownAmount = item.custom_amount ?? getKnownProposalAmount(item.name, answers);
  return typeof knownAmount === "number" && knownAmount > 0;
}

function isGuidanceLockedProposal(
  item: EnvelopeProposalResolved,
  guidanceSnapshot: GuidanceDirectionSnapshot | null
): boolean {
  const normalizedName = normalizeProposalName(item.name);
  if (normalizedName === "Imprévus / طوارئ" || normalizedName === "المرونة") return true;
  if (!guidanceSnapshot) return false;
  if (item.group_key === "debts" && guidanceSnapshot.planned_debt > 0) return true;
  if (item.group_key === "goals" && guidanceSnapshot.planned_goals > 0) return true;
  return false;
}

function resolveProposalLockReason(
  item: EnvelopeProposalResolved,
  answers: Answers,
  guidanceSnapshot: GuidanceDirectionSnapshot | null
): ProposalLockReason {
  if (isGuidanceLockedProposal(item, guidanceSnapshot)) return "guidance_locked";
  if (isProposalFixedCommitmentLocked(item, answers)) return "fixed_commitment_locked";
  if (item.source === "custom") return "user_locked";
  return "none";
}

function getRiskPriorityOrder(
  pressureLevel: SalaryAmountPressureLevel | null
): EnvelopeProposalDomain[] {
  if (pressureLevel === "tight") {
    return [
      "essentials",
      "housing",
      "debts",
      "buffer",
      "transport",
      "bills",
      "family",
      "saving",
      "goals",
      "lifestyle",
      "pro",
    ];
  }
  if (pressureLevel === "managed") {
    return [
      "essentials",
      "housing",
      "transport",
      "debts",
      "buffer",
      "bills",
      "family",
      "saving",
      "goals",
      "lifestyle",
      "pro",
    ];
  }
  return [
    "essentials",
    "housing",
    "transport",
    "buffer",
    "bills",
    "family",
    "saving",
    "goals",
    "lifestyle",
    "debts",
    "pro",
  ];
}

function computeGoalFundingReadiness(
  answers: Answers,
  sanity: SanityMetrics,
  guidanceSnapshot: GuidanceDirectionSnapshot | null
): GoalFundingReadiness {
  const entries = getGoalBuilderEntries(answers);
  const requiredMonthlyTotal = roundAmount(
    entries.reduce((sum, entry) => {
      const reality = buildGoalRealityCheckForEntry(entry, answers);
      return sum + (reality.required_monthly ?? 0);
    }, 0)
  );
  const manualGoalsMonthlyTotal = roundAmount(
    entries.reduce((sum, entry) => {
      const manual = Math.max(
        0,
        toNumber(getString(answers, `G1_goal_monthly_amount_${entry.index}`))
      );
      return sum + manual;
    }, 0)
  );
  const guidancePlannedGoalsFromAnswers = Math.max(
    0,
    toNumber(getString(answers, "F1_guidance_planned_goals"))
  );
  const plannedMonthlyTotal = roundAmount(
    Math.max(0, guidanceSnapshot?.planned_goals ?? 0, guidancePlannedGoalsFromAnswers, manualGoalsMonthlyTotal)
  );
  const availableMonthlyCapacity = roundAmount(
    Math.max(
      0,
      (sanity.remaining ?? 0) - buildDebtSummaryMetrics(answers).current_monthly
    )
  );
  const gapMonthly = roundAmount(Math.max(0, requiredMonthlyTotal - plannedMonthlyTotal));
  const status =
    requiredMonthlyTotal <= 0
      ? "ready"
      : plannedMonthlyTotal >= requiredMonthlyTotal
      ? "ready"
      : plannedMonthlyTotal > 0
      ? "partial"
      : "blocked";

  return {
    required_monthly_total: requiredMonthlyTotal,
    planned_monthly_total: plannedMonthlyTotal,
    available_monthly_capacity: availableMonthlyCapacity,
    gap_monthly: gapMonthly,
    status,
  };
}

function getGuidanceBudgetForGroup(
  groupKey: EnvelopeProposalDomain,
  guidanceSnapshot: GuidanceDirectionSnapshot | null,
  answers: Answers
): { amount: number | null; label: string | null; hint: string | null } {
  if (!guidanceSnapshot) {
    return { amount: null, label: null, hint: null };
  }

  if (groupKey === "debts") {
    return {
      amount: guidanceSnapshot.planned_debt,
      label: "توجيه",
      hint:
        guidanceSnapshot.planned_debt > 0
          ? "هنا كنبيّنو غير شحال من الميزانية بغينا نوجهو لجهة الديون. الأقساط اللي باينين فالأظرفة لتحت."
          : "هاد المرة الديون ما خذاوش دفعة كبيرة بوحدهم.",
    };
  }

  if (groupKey === "buffer") {
    return {
      amount: guidanceSnapshot.keep_safety ? guidanceSnapshot.planned_reserve : 0,
      label: "غلاف الأمان",
      hint: guidanceSnapshot.keep_safety
        ? "ظرف الأمان هو الأصل هنا. اللي لتحت غير تفاصيل كتخدم داخل نفس الغلاف."
        : "فالتوجيه اخترتي ما تفتّحش غلاف مستقل للأمان دابا.",
    };
  }

  if (groupKey === "goals") {
    const hasConcreteGoals = getGoalBuilderEntries(answers).length > 0;
    return {
      amount: hasConcreteGoals ? guidanceSnapshot.planned_goals : null,
      label: "توجيه",
      hint: !hasConcreteGoals
        ? "التوجيه يقدر يخلي مساحة للأهداف، ولكن دابا ما كاين حتى هدف كامل باش يبان هنا."
        : guidanceSnapshot.planned_goals > 0
          ? "هنا كنبيّنو شحال من الميزانية غادي تمشي للأهداف."
          : "فهاد الاتجاه الأهداف ما خذاوش دفعة كبيرة بوحدهم.",
    };
  }

  if (groupKey === "lifestyle") {
    return {
      amount: guidanceSnapshot.keep_flex ? guidanceSnapshot.planned_flex : 0,
      label: "غلاف المرونة",
      hint: guidanceSnapshot.keep_flex
        ? "ظرف المرونة هو الأصل هنا. الأظرفة اللي لتحت كيتصرفو من نفس الهامش."
        : "فالتوجيه اخترتي ما تفتّحش غلاف مستقل للمرونة دابا.",
    };
  }

  if (groupKey === "saving") {
    return {
      amount: guidanceSnapshot.mode === "stability_first" ? guidanceSnapshot.planned_free : null,
      label: guidanceSnapshot.mode === "stability_first" ? "الباقي الحر" : null,
      hint:
        guidanceSnapshot.mode === "stability_first"
          ? "هاد الجزء باقي ما تعيّنش نهائياً، وتقدر من بعد تقرر فين بغيتي تمشّيه."
          : null,
    };
  }

  return { amount: null, label: null, hint: null };
}

function toSuggestedEnvelopeGroups(answers: Answers): QuestionOptionGroup[] {
  const relevantKeys = getRelevantSuggestionGroupKeys(answers);
  const groups = ENVELOPE_SUGGESTION_CATALOG.filter((group) => relevantKeys.includes(group.key))
    .map((group) => {
      const names = uniqueBySlug(filterGroupNamesByContext(group.key, group.names, answers));
      return {
        id: group.key,
        title: ENVELOPE_GROUP_TITLE_DARIJA[group.key] ?? group.title,
        options: names.map((name) => ({
          value: slugify(name),
          label: getEnvelopeLabelForUi(name),
        })),
      };
    })
    .filter((group) => group.options.length > 0);

  const used = new Set<string>();
  return groups.map((group) => ({
    ...group,
    options: group.options.filter((option) => {
      if (used.has(option.value)) return false;
      used.add(option.value);
      return true;
    }),
  }));
}

function toSuggestedEnvelopeOptions(answers: Answers): QuestionOption[] {
  return toSuggestedEnvelopeGroups(answers).flatMap((group) => group.options);
}

function deriveValidatedSuggestedEnvelopes(answers: Answers): string[] {
  const mode = getString(answers, "E9_generate_confirm") || "yes_generate";
  if (mode !== "yes_generate") return [];
  const options = toSuggestedEnvelopeOptions(answers);
  const selected = new Set(getList(answers, "E10_keep_suggestions"));
  const names = options
    .filter((option) => selected.has(option.value))
    .map((option) => option.label);
  return uniqueBySlug(names);
}

function deriveEnvelopes(answers: Answers): string[] {
  const validatedSuggestions = deriveValidatedSuggestedEnvelopes(answers);
  const custom = parseCsvNames(getString(answers, "C1_custom_envelopes"));
  let names: string[] = [...validatedSuggestions, ...custom];

  if (names.length === 0) {
    deriveSelectedDomains(answers).forEach((domain) => {
      names.push(...(DOMAIN_TO_ENVELOPES[domain] ?? []));
    });
  }

  if (names.length === 0) {
    names = ["Courses", "Transport", "Factures"];
  }

  names.push("Cash", "Épargne");
  return Array.from(new Set(names));
}

function deriveCategories(answers: Answers): string[] {
  const categories: string[] = [];
  deriveSelectedDomains(answers).forEach((domain) => {
    categories.push(...(DOMAIN_TO_CATEGORIES[domain] ?? []));
  });
  if (categories.length === 0) {
    categories.push("Courses", "Transport", "Factures");
  }
  return Array.from(new Set(categories));
}

function computeSanity(answers: Answers): SanityMetrics {
  const incomeType = getString(answers, "Q0_income_type");
  const normalizationFlags: string[] = [];

  let incomeEstimate: number | null = null;
  if (incomeType === "salaried") {
    incomeEstimate = toNumber(getString(answers, "S2a_salary_amount")) || null;
  }
  if (incomeType === "hirafi") {
    const normalizedProfile = normalizeHirafiIncomeProfile(answers);
    incomeEstimate = normalizedProfile.min || null;
    normalizationFlags.push(...normalizedProfile.flags);
  }
  if (incomeType === "freelancer") {
    incomeEstimate = toNumber(getString(answers, "F7_min_income")) || null;
  }
  if (incomeType === "mixed") {
    incomeEstimate = toNumber(getString(answers, "M3_min_income")) || null;
  }

  const fixedItems = getList(answers, "FX1_fixed_items");
  const fixedFromSetup = fixedItems.reduce((sum, item) => {
    if (item === "other") return sum;
    const amount = toNumber(getString(answers, `FX2_amount_${item}`));
    return sum + amount;
  }, 0);
  const fixedOtherRows = getFixedOtherRows(answers);
  const fixedOtherMonthlyTotal = fixedOtherRows.reduce(
    (sum, row) => sum + toMonthlyAmountFromFixedOtherCadence(row.amount, row.cadence, answers),
    0
  );
  const fixedRentAmount = toNumber(getString(answers, "RNT0_rent_amount"));
  const housingLoanAmount = toNumber(getString(answers, "HSN1_loan_monthly_amount"));

  const publicTransportAmount = toNumber(getString(answers, "TRP1_public_monthly_amount"));
  const publicTaxiAmount = toNumber(getString(answers, "TRP1_taxi_monthly_amount"));

  const totalCarTransport = getCarTransportPrefixes(answers).reduce(
    (sum, prefix) => sum + getCarTransportMonthlyTotalForPrefix(answers, prefix),
    0
  );

  const totalBikeTransport = getBikeTransportPrefixes(answers).reduce(
    (sum, prefix) => sum + getBikeTransportMonthlyTotalForPrefix(answers, prefix),
    0
  );

  const mixedTransportTotal = shouldUseMixedTransportTotal(answers)
    ? toNumber(getString(answers, "TRX2_total_monthly_amount"))
    : 0;

  const fixedCommitmentsUiTotal =
    fixedFromSetup +
    fixedOtherMonthlyTotal +
    getFamilySupportMonthlyAmount(answers) +
    fixedRentAmount +
    housingLoanAmount;

  const transportEssentialTotal =
    publicTransportAmount +
    publicTaxiAmount +
    totalCarTransport +
    totalBikeTransport +
    mixedTransportTotal;
  const essentialLoadTotal = fixedCommitmentsUiTotal + transportEssentialTotal;

  if (transportEssentialTotal > 0 && getIncomeCadenceForRecurringCosts(answers) !== "monthly") {
    normalizationFlags.push("transport_included_in_essential_load");
  }

  const goalsTotalPerIncome = 0;

  const remaining =
    incomeEstimate !== null && incomeEstimate > 0
      ? Number((incomeEstimate - essentialLoadTotal - goalsTotalPerIncome).toFixed(2))
      : null;

  return {
    incomeEstimate,
    fixedTotal: Number(essentialLoadTotal.toFixed(2)),
    fixedCommitmentsUiTotal: Number(fixedCommitmentsUiTotal.toFixed(2)),
    essentialLoadTotal: Number(essentialLoadTotal.toFixed(2)),
    normalizationFlags: Array.from(new Set(normalizationFlags)),
    goalsTotalPerIncome: Number(goalsTotalPerIncome.toFixed(2)),
    remaining,
    splitTotal: 100,
    splitKeys: [],
  };
}

function getSalaryIncomeBand(incomeEstimate: number): SalaryAmountIncomeBand {
  if (incomeEstimate < 4500) return "starter";
  if (incomeEstimate < 9000) return "steady";
  return "strong";
}

function getSalaryPressureLevel(
  incomeEstimate: number,
  fixedLoadRatio: number,
  remainingAfterGoals: number
): SalaryAmountPressureLevel {
  if (fixedLoadRatio >= 0.75 || remainingAfterGoals <= incomeEstimate * 0.12) return "tight";
  if (fixedLoadRatio >= 0.55 || remainingAfterGoals <= incomeEstimate * 0.35) return "managed";
  return "comfortable";
}

function getRealisticGoalMonthlyCapFromSanity(sanity: SanityMetrics): number | null {
  const monthlyIncome = sanity.incomeEstimate;
  if (!monthlyIncome || monthlyIncome <= 0) return null;

  const essentialLoad = getSanityEssentialLoadTotal(sanity);
  const remainingAfterFixed = roundAmount(Math.max(0, monthlyIncome - essentialLoad));
  const fixedLoadRatio = essentialLoad > 0 ? essentialLoad / monthlyIncome : 0;
  const pressureLevel = getSalaryPressureLevel(monthlyIncome, fixedLoadRatio, remainingAfterFixed);

  return roundAmount(
    Math.max(
      0,
      Math.min(
        monthlyIncome *
          (pressureLevel === "tight" ? 0.06 : pressureLevel === "managed" ? 0.12 : 0.18),
        remainingAfterFixed *
          (pressureLevel === "tight" ? 0.25 : pressureLevel === "managed" ? 0.4 : 0.55)
      )
    )
  );
}

function getMonthsUntilGoal(goalDateRaw: string): number | null {
  if (!goalDateRaw) return null;
  const goalDate = new Date(goalDateRaw);
  if (Number.isNaN(goalDate.getTime())) return null;

  const now = new Date();
  const diffMs = goalDate.getTime() - now.getTime();
  if (diffMs <= 0) return 0;

  const months = Math.ceil(diffMs / (1000 * 60 * 60 * 24 * 30.4375));
  return Math.max(1, months);
}

function getCyclesUntilFutureDate(targetDateRaw: string, answers: Answers): number | null {
  if (!targetDateRaw) return null;
  const targetDate = new Date(targetDateRaw);
  if (Number.isNaN(targetDate.getTime())) return null;

  const now = new Date();
  const diffMs = targetDate.getTime() - now.getTime();
  if (diffMs <= 0) return 0;

  const intervalDays = getSweepIntervalDaysForAnswers(answers);
  return Math.max(1, Math.ceil(diffMs / (1000 * 60 * 60 * 24 * intervalDays)));
}

function addMonths(date: Date, months: number): Date {
  const next = new Date(date);
  next.setMonth(next.getMonth() + months);
  return next;
}

function formatCoverageMonths(value: number | null): string {
  if (!value || value <= 0) return "0 شهر";
  const rounded = Math.round(value * 10) / 10;
  return `${String(rounded).replace(".", ",")} شهر`;
}

function addDays(date: Date, days: number): Date {
  const next = new Date(date);
  next.setDate(next.getDate() + days);
  return next;
}

function buildDebtTargetRealityCheck(
  answers: Answers,
  options?: { includeFutureExtraMonthly?: boolean }
): DebtTargetRealityCheck {
  const cycleLabel = getCycleContributionLabel(answers);
  if (getString(answers, "E5_has_debt") !== "yes") {
    return {
      status: "unknown",
      total_remaining: 0,
      current_monthly: 0,
      current_per_cycle: 0,
      cycle_label: cycleLabel,
      cycle_count_to_target: null,
      required_monthly: null,
      required_per_cycle: null,
      realistic_capacity_monthly: null,
      realistic_capacity_per_cycle: null,
      reserve_per_cycle: null,
      estimated_months_needed: null,
      estimated_cycles_needed: null,
      estimated_finish_date: null,
      focus_debt_name: null,
      debt_count: 0,
    };
  }

  const debtCount = getDebtCount(answers);
  let totalRemaining = 0;
  let currentMonthly = 0;
  const targetedDebts: Array<{ name: string; requiredPerCycle: number; targetDate: string }> = [];
  for (let i = 1; i <= debtCount; i += 1) {
    totalRemaining += toNumber(getString(answers, `D3_debt_remaining_amount_${i}`));
    currentMonthly += getDebtPaymentSnapshot(answers, i).monthly_equivalent;
    const targetDate = getString(answers, `D5a_debt_target_date_${i}`);
    const cyclesUntilTarget = getCyclesUntilFutureDate(targetDate, answers);
    const debtRemaining = toNumber(getString(answers, `D3_debt_remaining_amount_${i}`));
    if (targetDate && cyclesUntilTarget && cyclesUntilTarget > 0 && debtRemaining > 0) {
      targetedDebts.push({
        name: getString(answers, `D2_debt_name_${i}`) || `Debt ${i}`,
        requiredPerCycle: roundAmount(debtRemaining / cyclesUntilTarget),
        targetDate,
      });
    }
  }

  if (options?.includeFutureExtraMonthly && getString(answers, "D8_debt_extra_monthly") === "yes") {
    currentMonthly += toMonthlyAmountFromCycle(toNumber(getString(answers, "D8a_debt_extra_amount")), answers);
  }

  const currentPerCycle = toCycleAmount(currentMonthly, answers);
  const sanity = computeSanity(answers);
  const incomePerCycle = sanity.incomeEstimate ? toCycleAmount(sanity.incomeEstimate, answers) : 0;
  const fixedPerCycle = toCycleAmount(getSanityEssentialLoadTotal(sanity), answers);
  let minimumDebtMonthly = 0;
  for (let i = 1; i <= debtCount; i += 1) {
    minimumDebtMonthly += getDebtPaymentSnapshot(answers, i).monthly_equivalent;
  }
  const minimumDebtPerCycle = toCycleAmount(
    minimumDebtMonthly,
    answers
  );
  const remainingAfterCorePerCycle = Math.max(0, incomePerCycle - fixedPerCycle - minimumDebtPerCycle);
  const reservePerCycle = roundAmount(remainingAfterCorePerCycle * 0.3);
  const realisticExtraPerCycle = roundAmount(remainingAfterCorePerCycle * 0.7);
  const realisticCapacityPerCycle = roundAmount(minimumDebtPerCycle + realisticExtraPerCycle);
  const realisticCapacityMonthly = toMonthlyAmountFromCycle(realisticCapacityPerCycle, answers);
  const requiredPerCycle = targetedDebts.length
    ? roundAmount(
        targetedDebts.reduce((sum, debt) => sum + Math.max(0, debt.requiredPerCycle), 0)
      )
    : null;
  const requiredMonthly = requiredPerCycle !== null ? toMonthlyAmountFromCycle(requiredPerCycle, answers) : null;
  const focusDebt =
    targetedDebts
      .slice()
      .sort((left, right) => left.requiredPerCycle - right.requiredPerCycle || left.targetDate.localeCompare(right.targetDate))[0]
      ?.name ?? null;

  if (totalRemaining <= 0 || currentMonthly <= 0) {
    return {
      status: "unknown",
      total_remaining: totalRemaining,
      current_monthly: currentMonthly,
      current_per_cycle: currentPerCycle,
      cycle_label: cycleLabel,
      cycle_count_to_target: null,
      required_monthly: null,
      required_per_cycle: null,
      realistic_capacity_monthly: realisticCapacityMonthly,
      realistic_capacity_per_cycle: realisticCapacityPerCycle,
      reserve_per_cycle: reservePerCycle,
      estimated_months_needed: null,
      estimated_cycles_needed: null,
      estimated_finish_date: null,
      focus_debt_name: focusDebt,
      debt_count: debtCount,
    };
  }

  const estimatedMonthsNeeded = Math.max(1, Math.ceil(totalRemaining / currentMonthly));
  const estimatedCyclesNeeded = Math.max(1, Math.ceil(totalRemaining / Math.max(currentPerCycle, 1)));
  const estimatedFinishDate = addMonths(new Date(), estimatedMonthsNeeded);

  let status: DebtTargetRealityStatus = "realistic";
  if (requiredPerCycle !== null) {
    if (realisticCapacityPerCycle <= 0 || requiredPerCycle > realisticCapacityPerCycle * 1.6) {
      status = "impossible_now";
    } else if (requiredPerCycle > realisticCapacityPerCycle * 1.2) {
      status = "unrealistic";
    } else if (requiredPerCycle > realisticCapacityPerCycle) {
      status = "ambitious";
    }
  }

  return {
    status,
    total_remaining: totalRemaining,
    current_monthly: currentMonthly,
    current_per_cycle: currentPerCycle,
    cycle_label: cycleLabel,
    cycle_count_to_target: targetedDebts.length ? targetedDebts.length : null,
    required_monthly: requiredMonthly,
    required_per_cycle: requiredPerCycle,
    realistic_capacity_monthly: realisticCapacityMonthly,
    realistic_capacity_per_cycle: realisticCapacityPerCycle,
    reserve_per_cycle: reservePerCycle,
    estimated_months_needed: estimatedMonthsNeeded,
    estimated_cycles_needed: estimatedCyclesNeeded,
    estimated_finish_date: estimatedFinishDate,
    focus_debt_name: focusDebt,
    debt_count: debtCount,
  };
}

function getDebtFocusOptionsForUi(answers: Answers): QuestionOption[] {
  const count = getDebtCount(answers);
  return Array.from({ length: count }).map((_, index) => {
    const i = index + 1;
    const debtName = getString(answers, `D2_debt_name_${i}`) || `الدين ${i}`;
    return {
      value: String(i),
      label: debtName,
    };
  });
}

function getSuggestedDebtExtraPerCycle(answers: Answers): number {
  const debtReality = buildDebtTargetRealityCheck(answers);
  let totalMinimumMonthly = 0;
  for (let i = 1; i <= getDebtCount(answers); i += 1) {
    totalMinimumMonthly += getDebtPaymentSnapshot(answers, i).monthly_equivalent;
  }
  const minimumPerCycle = toCycleAmount(
    totalMinimumMonthly,
    answers
  );
  const extraCapacity = Math.max(
    0,
    roundAmount((debtReality.realistic_capacity_per_cycle ?? 0) - minimumPerCycle)
  );
  return extraCapacity;
}

function getChosenDebtExtraPerCycle(answers: Answers): number {
  if (getString(answers, "D8_debt_extra_monthly") !== "yes") return 0;
  const chosen = toNumber(getString(answers, "D8a_debt_extra_amount"));
  return chosen > 0 ? chosen : getSuggestedDebtExtraPerCycle(answers);
}

function buildDebtPlanPreview(answers: Answers): DebtPlanPreviewItem[] {
  if (getString(answers, "E5_has_debt") !== "yes") return [];

  const debtCount = getDebtCount(answers);
  const cycleDays = getSweepIntervalDaysForAnswers(answers);
  let minimumBudgetPerCycle = 0;
  for (let i = 1; i <= debtCount; i += 1) {
    minimumBudgetPerCycle += getDebtPaymentSnapshot(answers, i).cycle_equivalent;
  }
  const totalBudgetPerCycle = roundAmount(minimumBudgetPerCycle + getChosenDebtExtraPerCycle(answers));
  const strategy = getDebtLegacyStrategy(answers);
  const selectedFocusIndex = getDebtFocusIndex(answers);
  const rows = Array.from({ length: debtCount })
    .map((_, index) => {
      const i = index + 1;
      const name = getString(answers, `D2_debt_name_${i}`);
      const remaining = toNumber(getString(answers, `D3_debt_remaining_amount_${i}`));
      const minimumPerCycle = getDebtPaymentSnapshot(answers, i).cycle_equivalent;
      if (!name || remaining <= 0 || minimumPerCycle < 0) return null;
      return {
        index: i,
        name,
        remaining,
        minimumPerCycle,
        targetDate: getString(answers, `D5a_debt_target_date_${i}`) || null,
        estimatedFinishCycle: null as number | null,
        currentCyclePayment: 0,
      };
    })
    .filter((item): item is NonNullable<typeof item> => Boolean(item));

  if (rows.length === 0) return [];

  const focusIndex =
    selectedFocusIndex > 0 && rows.some((item) => item.index === selectedFocusIndex)
      ? selectedFocusIndex
      : rows[0].index;

  const focusOrder = rows
    .slice()
    .sort((left, right) => {
      if (left.index === focusIndex) return -1;
      if (right.index === focusIndex) return 1;
      if (left.targetDate && right.targetDate) return left.targetDate.localeCompare(right.targetDate);
      if (left.targetDate) return -1;
      if (right.targetDate) return 1;
      return left.remaining - right.remaining;
    })
    .map((item) => item.index);

  const active = rows.map((item) => ({
    ...item,
    remainingNow: item.remaining,
  }));

  for (let cycle = 1; cycle <= 720; cycle += 1) {
    const activeRows = active.filter((item) => item.remainingNow > 0.01);
    if (activeRows.length === 0) break;

    let budgetLeft = totalBudgetPerCycle;
    const allocations = new Map<number, number>();

    for (const item of activeRows) {
      const minimum = Math.min(item.minimumPerCycle, item.remainingNow);
      allocations.set(item.index, minimum);
      budgetLeft = Math.max(0, budgetLeft - minimum);
    }

    if (budgetLeft > 0) {
      if (strategy === "balanced") {
        const totalRemaining = activeRows.reduce((sum, item) => sum + item.remainingNow, 0);
        for (const item of activeRows) {
          if (totalRemaining <= 0) break;
          const current = allocations.get(item.index) ?? 0;
          const extraShare = roundAmount((budgetLeft * item.remainingNow) / totalRemaining);
          allocations.set(item.index, Math.min(item.remainingNow, current + extraShare));
        }
      } else {
        for (const targetIndex of focusOrder) {
          if (budgetLeft <= 0.01) break;
          const item = activeRows.find((row) => row.index === targetIndex);
          if (!item) continue;
          const current = allocations.get(item.index) ?? 0;
          const room = Math.max(0, item.remainingNow - current);
          if (room <= 0) continue;
          const applied = Math.min(room, budgetLeft);
          allocations.set(item.index, current + applied);
          budgetLeft = roundAmount(Math.max(0, budgetLeft - applied));
        }
      }
    }

    for (const item of activeRows) {
      const payment = roundAmount(allocations.get(item.index) ?? 0);
      if (cycle === 1) item.currentCyclePayment = payment;
      item.remainingNow = roundAmount(Math.max(0, item.remainingNow - payment));
      if (item.remainingNow <= 0.01 && item.estimatedFinishCycle === null) {
        item.estimatedFinishCycle = cycle;
      }
    }
  }

  const today = new Date();
  return active.map((item) => {
    const finishDate = item.estimatedFinishCycle ? addDays(today, item.estimatedFinishCycle * cycleDays) : null;
    const status =
      item.targetDate && finishDate
        ? finishDate <= new Date(`${item.targetDate}T23:59:59`)
          ? "on_track"
          : "later_than_target"
        : "no_target";
    return {
      index: item.index,
      name: item.name,
      minimum_per_cycle: roundAmount(item.minimumPerCycle),
      extra_per_cycle: roundAmount(Math.max(0, (item.currentCyclePayment || item.minimumPerCycle) - item.minimumPerCycle)),
      payment_per_cycle: roundAmount(item.currentCyclePayment || item.minimumPerCycle),
      payment_monthly: toMonthlyAmountFromCycle(roundAmount(item.currentCyclePayment || item.minimumPerCycle), answers),
      estimated_finish_date: finishDate,
      target_date: item.targetDate,
      status,
    };
  });
}

function buildGoalRealityCheck(answers: Answers): GoalRealityCheck {
  const goalEntries = getGoalBuilderEntries(answers);
  if (goalEntries.length > 0) {
    return buildGoalRealityCheckForEntry(goalEntries[0], answers);
  }

  return buildGoalRealityCheckForEntry(
    {
      target_amount: toNumber(getString(answers, "G2_goal_amount")),
      current_amount: 0,
      target_date: getString(answers, "G3_goal_date") || null,
    },
    answers
  );
}

function buildSalaryAmountEffects(
  answers: Answers,
  sanity: SanityMetrics,
  salaryScheduleProfile: SalaryScheduleProfile | null,
  objectivePolicy: ObjectivePolicy
): SalaryAmountEffects | null {
  if (getString(answers, "Q0_income_type") !== "salaried") return null;
  const monthlyIncome = sanity.incomeEstimate;
  if (!monthlyIncome || monthlyIncome <= 0) return null;

  const essentialLoad = getSanityEssentialLoadTotal(sanity);
  const remainingAfterFixed = roundAmount(Math.max(0, monthlyIncome - essentialLoad));
  const remainingAfterGoals = roundAmount(
    Math.max(0, monthlyIncome - essentialLoad - sanity.goalsTotalPerIncome)
  );
  const fixedLoadRatio = essentialLoad > 0 ? essentialLoad / monthlyIncome : 0;
  const remainingRatio = remainingAfterGoals / monthlyIncome;
  const incomeBand = getSalaryIncomeBand(monthlyIncome);
  const pressureLevel = getSalaryPressureLevel(monthlyIncome, fixedLoadRatio, remainingAfterGoals);
  const realisticGoalMonthlyCap = getRealisticGoalMonthlyCapFromSanity(sanity) ?? 0;
  const emergencySeedMonthly = roundAmount(
    Math.max(
      0,
      Math.min(
        remainingAfterGoals *
          (pressureLevel === "tight" ? 0.12 : pressureLevel === "managed" ? 0.18 : 0.24),
        monthlyIncome *
          (pressureLevel === "tight" ? 0.04 : pressureLevel === "managed" ? 0.07 : 0.1)
      )
    )
  );
  const frequency =
    salaryScheduleProfile?.frequency ??
    (getString(answers, "S3_frequency") || "monthly");
  const expectedIncomePerEntry = getExpectedSalaryAmountPerEntry(monthlyIncome, frequency);
  const expectedIncomeEntryLabel = getSalaryEntryFrequencyLabel(frequency);
  const projectionWeeklyAvailable = roundAmount(remainingAfterGoals / 4.33);
  const projectionDailyAvailable = roundAmount(remainingAfterGoals / 30);

  const envelopeHighlightGroups: EnvelopeProposalDomain[] =
    pressureLevel === "tight"
      ? ["essentials", "housing", "transport", "bills", "buffer"]
      : pressureLevel === "comfortable"
      ? objectivePolicy.mode === "save"
        ? ["saving", "buffer", "goals", "essentials"]
        : ["buffer", "saving", "essentials", "lifestyle"]
      : ["essentials", "buffer", "bills", "transport", "saving"];

  const envelopeHelperCopy =
    pressureLevel === "tight"
      ? "بهاد الدخل الحالي، خففنا اللائحة وركزنا أكثر على الضروريات والاحتياط."
      : pressureLevel === "managed"
      ? "الدخل الحالي كيسمح بتنظيم مزيان، ولكن الأولوية بقات للثابت والاحتياط."
      : "الدخل الحالي كيعطيك مساحة باش تزيد التوفير والأهداف بلا ما تضغط على اليومي.";

  const dashboardSummary =
    pressureLevel === "tight"
      ? "Dashboard preview: خاص المصاريف الثابتة تبقى واضحة بزاف وكل زيادة تتحسب."
      : pressureLevel === "managed"
      ? "Dashboard preview: عندك مساحة معقولة، ولكن خصك تبقى محافظ على التوازن."
      : "Dashboard preview: عندك مرونة أكبر باش التوفير والأهداف يبان لهم أثر أسرع.";

  const sanityAlerts: SalaryAmountSanityAlert[] = [
    fixedLoadRatio >= 0.75
      ? {
          tone: "danger",
          title: "الالتزامات الثابتة طالعة",
          value: formatPercent(fixedLoadRatio),
          message: "جزء كبير من الراتب غادي مباشرة للثابت، لذلك خففنا التعقيد فالأظرفة.",
        }
      : fixedLoadRatio >= 0.55
      ? {
          tone: "warning",
          title: "الثابت واخد حصة مهمة",
          value: formatPercent(fixedLoadRatio),
          message: "بان لينا خاص الأولوية تبقى للثابت والاحتياط قبل المصاريف الثانوية.",
        }
      : {
          tone: "success",
          title: "الثابت متحكم فيه",
          value: formatPercent(fixedLoadRatio),
          message: "عندك مساحة أحسن باش التوفير والأهداف يبان لهم أثر فالدashboard.",
        },
    sanity.goalsTotalPerIncome > 0 && sanity.goalsTotalPerIncome > realisticGoalMonthlyCap
      ? {
          tone: "warning",
          title: "هدف شهري طالع شوية",
          value: formatMad(sanity.goalsTotalPerIncome),
          message: `الاقتراح الواقعي دابا هو تقريباً ${formatMad(realisticGoalMonthlyCap)} فالشهر.`,
        }
      : {
          tone: "neutral",
          title: "الهدف الشهري الواقعي",
          value: formatMad(realisticGoalMonthlyCap),
          message: "هنا كنقدرو شحال تقدر تخصص للهدف بلا ما تخنق المصروف اليومي.",
        },
    {
      tone: remainingAfterGoals <= monthlyIncome * 0.18 ? "warning" : "success",
      title: "المساحة اللي كتبقى ليك",
      value: formatMad(remainingAfterGoals),
      message:
        remainingAfterGoals <= monthlyIncome * 0.18
          ? "الباقي محدود، لذلك projections والدashboard خصهم يبانو بشكل محافظ."
          : "هاد الباقي هو اللي كنستعملوه فـ projections واليومي والتوفير.",
    },
  ];

  return {
    source_question: "S2a_salary_amount",
    enabled: true,
    monthly_income_estimate: monthlyIncome,
    expected_income_per_entry: expectedIncomePerEntry,
    expected_income_entry_label: expectedIncomeEntryLabel,
    fixed_commitments_monthly: essentialLoad,
    fixed_load_ratio: fixedLoadRatio,
    goals_monthly: sanity.goalsTotalPerIncome,
    remaining_after_fixed: remainingAfterFixed,
    remaining_after_goals: remainingAfterGoals,
    remaining_ratio: remainingRatio,
    income_band: incomeBand,
    pressure_level: pressureLevel,
    realistic_goal_monthly_cap: realisticGoalMonthlyCap,
    emergency_seed_monthly: emergencySeedMonthly,
    dashboard_summary: dashboardSummary,
    envelope_helper_copy: envelopeHelperCopy,
    envelope_highlight_groups: envelopeHighlightGroups,
    projection_weekly_available: projectionWeeklyAvailable,
    projection_daily_available: projectionDailyAvailable,
    sanity_alerts: sanityAlerts,
  };
}

function applyHouseholdSelectionDefaults(answers: Answers, householdType: string): Answers {
  const next: Answers = { ...answers, E0_household_type: householdType };

  if (householdType === "single") {
    next.E1_adults_count = "1";
    next.E2_kids_count = "0";
  } else if (householdType === "couple") {
    next.E1_adults_count = "2";
  } else if (householdType === "extended_family") {
    next.E2_kids_count = "0";
  }

  return next;
}

