  const validateSweepSetupFields = useCallback(() => {
    const rawDate = getString(answers, "SWP1_last_income_date").trim();
    const rawAmount = getString(answers, "SWP2_last_income_amount").trim();
    if (!rawDate) {
      setValidationFeedback("اختار آخر تاريخ توصلتي فيه بالدخل.");
      return false;
    }
    const parsedDate = new Date(`${rawDate}T00:00:00`);
    if (Number.isNaN(parsedDate.getTime())) {
      setValidationFeedback("هاد التاريخ ما باينش صحيح.");
      return false;
    }
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (parsedDate > today) {
      setValidationFeedback("تاريخ آخر دخل خاصو يكون اليوم ولا شي نهار فات، ماشي فالمستقبل.");
      return false;
    }

    const amountValue = toNumber(rawAmount);
    if (amountValue <= 0) {
      setValidationFeedback("دخل مبلغ صحيح وآراه يكون موجب.");
      return false;
    }

    clearValidationState();
    return true;
  }, [answers, clearValidationState, setValidationFeedback]);

